package dev.dong4j.zeka.starter.endpoint.autoconfigure;

import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.AutoConfigureAfter;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.starter.endpoint.autoconfigure.reactive.ReactiveStartInfoAutoConfiguration;
import dev.dong4j.zeka.starter.endpoint.autoconfigure.servlet.ServletStartInfoAutoConfiguration;
import dev.dong4j.zeka.starter.endpoint.constant.Endpoint;
import dev.dong4j.zeka.starter.endpoint.initialization.InitializationService;
import dev.dong4j.zeka.starter.endpoint.initialization.PreloadComponent;
import lombok.extern.slf4j.Slf4j;

/**
 * Endpoint 模块主自动配置类
 * <p>
 * 该类为 cubo-endpoint-spring-boot 模块提供主要的自动配置功能，
 * 负责根据不同的 Web 环境（Servlet 或 Reactive）加载相应的组件。
 * <p>
 * 主要功能：
 * 1. 根据配置属性控制是否启用 Endpoint 功能
 * 2. 仅在 Web 环境下生效
 * 3. 在 Servlet 和 Reactive 配置后加载
 * 4. 创建预热组件用于应用启动时的性能优化
 * <p>
 * 使用多个条件注解确保在适当的环境下才会生效。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2025.06.28 18:09
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@ConditionalOnEnabled(value = EndpointProperties.PREFIX)
@ConditionalOnWebApplication
@AutoConfigureAfter(value = {
    ServletStartInfoAutoConfiguration.class,
    ReactiveStartInfoAutoConfiguration.class
})
@ConditionalOnClass(Endpoint.class)
@EnableConfigurationProperties(EndpointProperties.class)
public class EndpointAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 构造方法
     * <p>
     * 输出启动日志，标识该自动配置类已被加载。
     */
    public EndpointAutoConfiguration() {
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 创建预热组件
     * <p>
     * 创建 PreloadComponent Bean，用于在应用启动完成后执行预热操作。
     * 使用 ObjectProvider 以支持可选的依赖注入，如果没有对应的
     * InitializationService 实现则传入 null。
     *
     * @param provider InitializationService 的可选提供者
     * @return PreloadComponent 实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(PreloadComponent.class)
    public PreloadComponent preloadComponent(ObjectProvider<InitializationService> provider) {
        return new PreloadComponent(provider.getIfAvailable());
    }
}

package dev.dong4j.zeka.starter.endpoint.autoconfigure.reactive;

import org.jetbrains.annotations.NotNull;
import org.springframework.boot.actuate.endpoint.annotation.ReadOperation;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.MediaType;
import org.springframework.web.reactive.config.WebFluxConfigurer;
import org.springframework.web.reactive.function.BodyInserters;
import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.reactive.function.server.RequestPredicates;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.RouterFunctions;
import org.springframework.web.reactive.function.server.ServerResponse;

import java.io.IOException;
import java.io.InputStream;
import java.io.Serializable;
import java.net.URI;
import java.util.Properties;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.api.R;
import dev.dong4j.zeka.kernel.common.api.Result;
import dev.dong4j.zeka.kernel.common.constant.App;
import dev.dong4j.zeka.kernel.common.enums.LibraryEnum;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.util.ConfigKit;
import dev.dong4j.zeka.kernel.common.util.NetUtils;
import dev.dong4j.zeka.starter.endpoint.ReactiveEndpointLauncherInitiation;
import dev.dong4j.zeka.starter.endpoint.autoconfigure.EndpointProperties;
import dev.dong4j.zeka.starter.endpoint.initialization.InitializationService;
import dev.dong4j.zeka.starter.endpoint.reactive.ReactiveInitializationService;
import lombok.extern.slf4j.Slf4j;

/**
 * Reactive 环境下的启动信息自动配置类
 * <p>
 * 该类为 Spring WebFlux Reactive Web 环境提供启动信息和 Git 信息相关的配置。
 * 主要包括：
 * <p>
 * 1. 配置処理启动信息的路由函数，支持重定向到 Git 信息端点
 * 2. 提供读取 Git 属性信息的方法
 * 3. 配置 Reactive 环境下的初始化服务
 * <p>
 * 仅在 Reactive Web 环境下生效，使用条件注解确保兼容性。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.03.10 11:20
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@ConditionalOnEnabled(value = EndpointProperties.PREFIX)
@ConditionalOnClass(value = {WebFluxConfigurer.class, ReactiveEndpointLauncherInitiation.class})
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.REACTIVE)
public class ReactiveStartInfoAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 构造方法
     * <p>
     * 输出启动日志，标识该自动配置类已被加载。
     */
    public ReactiveStartInfoAutoConfiguration() {
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 配置启动信息路由函数
     * <p>
     * 如果在 classpath 下存在 git.properties 文件，则将访问 /start 的请求
     * 重定向到 /git 端点，用于显示 Git 相关信息。
     * <p>
     * 同时提供健康检查接口 /check，用于检查应用是否正常运行。
     * <p>
     * 使用 Reactive 方式处理请求和响应，支持非阻塞式操作。
     *
     * @return 路由函数定义
     * @since 1.0.0
     */
    @NotNull
    @Bean
    static RouterFunction<ServerResponse> routerFunction() {
        // 创建路由函数，将 GET /start 请求重定向到 Git 信息端点
        RouterFunction<ServerResponse> startRoute = RouterFunctions.route(
            // 匹配 GET 请求到 /start 路径
            RequestPredicates.GET(LibraryEnum.START_URL),
            // 返回临时重定向响应，重定向到本地 Git 信息端点
            request -> ServerResponse.temporaryRedirect(URI.create("http://"
                                                                   + NetUtils.getLocalHost()
                                                                   + ":"
                                                                   + ConfigKit.getPort()
                                                                   + ConfigKit.getContextPath()
                                                                   + "/git")).build());

        // 创建健康检查路由，返回 "ok" 状态
        RouterFunction<ServerResponse> checkRoute = RouterFunctions.route(
            // 匹配 GET 请求到 /check 路径
            RequestPredicates.GET("/check"),
            // 返回 JSON 格式的健康检查响应
            request -> ServerResponse.ok()
                .contentType(MediaType.APPLICATION_JSON)
                .body(BodyInserters.fromValue(R.succeed("ok"))));

        // 组合多个路由函数
        return startRoute.and(checkRoute);
    }

    /**
     * 获取 Git 相关信息
     * <p>
     * 读取 classpath 下的 git.properties 文件并返回其内容。
     * 如果文件不存在或读取失败，则返回简单的 "up" 字符串。
     * 该方法使用 @ReadOperation 注解，可以通过 Actuator 端点访问。
     *
     * @return Git 属性信息或默认状态
     * @since 1.0.0
     */
    @ReadOperation
    public Result<? extends Serializable> git() {
        // 获取类加载器
        ClassLoader classLoader = this.getClass().getClassLoader();
        // 尝试加载 git.properties 文件
        InputStream inputStream = classLoader.getResourceAsStream(App.GIT_CONFIG_FILE_NAME);
        // 如果文件存在，读取并返回其内容
        if (inputStream != null) {
            Properties properties = new Properties();
            try {
                properties.load(inputStream);
            } catch (IOException ignored) {
                // 忽略读取异常
            }
            return R.succeed(properties);
        }
        // 文件不存在时返回默认状态
        return R.succeed("up");
    }

    /**
     * 创建 Reactive 初始化服务
     * <p>
     * 在 Reactive 环境下创建初始化服务实现，用于应用预热。
     * 使用 WebClient.Builder 来构建 HTTP 客户端进行异步请求。
     * 仅在没有其他 InitializationService 实现时才会创建。
     *
     * @param webClientBuilder WebClient 构建器，由 Spring Boot 自动配置提供
     * @return ReactiveInitializationService 实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(InitializationService.class)
    public InitializationService reactiveInitializationService(WebClient.Builder webClientBuilder) {
        return new ReactiveInitializationService(webClientBuilder);
    }
}

package dev.dong4j.zeka.starter.endpoint.autoconfigure.servlet;

import org.springframework.boot.actuate.endpoint.annotation.ReadOperation;
import org.springframework.boot.actuate.endpoint.web.annotation.WebEndpoint;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.servlet.DispatcherServlet;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.api.R;
import dev.dong4j.zeka.kernel.common.api.Result;
import dev.dong4j.zeka.kernel.common.constant.App;
import dev.dong4j.zeka.kernel.common.enums.LibraryEnum;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.util.ConfigKit;
import dev.dong4j.zeka.starter.endpoint.ServletEndpointLauncherInitiation;
import dev.dong4j.zeka.starter.endpoint.autoconfigure.EndpointProperties;
import dev.dong4j.zeka.starter.endpoint.initialization.InitializationService;
import dev.dong4j.zeka.starter.endpoint.servlet.ServletInitializationService;
import jakarta.annotation.Resource;
import jakarta.servlet.Servlet;
import jakarta.servlet.http.HttpServletResponse;
import lombok.extern.slf4j.Slf4j;

/**
 * Servlet 环境下的启动信息自动配置类
 * <p>
 * 该类为传统的 Servlet Web 环境提供启动信息和 Git 信息相关的端点配置。
 * 主要包括：
 * <p>
 * 1. 创建用于显示应用版本和 Git 信息的 Actuator 端点
 * 2. 配置 Servlet 环境下的初始化服务
 * 3. 支持根据是否存在 git.properties 文件来提供不同的信息展示
 * <p>
 * 仅在 Servlet Web 环境下生效，使用条件注解确保兼容性。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.03.10 11:20
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@ConditionalOnEnabled(value = EndpointProperties.PREFIX)
@ConditionalOnClass(value = {Servlet.class, DispatcherServlet.class, ServletEndpointLauncherInitiation.class})
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
public class ServletStartInfoAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 构造方法
     * <p>
     * 输出启动日志，标识该自动配置类已被加载。
     */
    public ServletStartInfoAutoConfiguration() {
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 创建启动信息端点
     * <p>
     * 创建用于显示应用启动信息和 Git 相关信息的 Actuator 端点。
     * 该端点可以通过 /actuator/start 访问。
     *
     * @return StartInfoEndpoint 实例
     * @since 1.0.0
     */
    @Bean
    public StartInfoEndpoint startInfoEndpoint() {
        return new StartInfoEndpoint();
    }

    /**
     * 启动信息 Actuator 端点内部类
     * <p>
     * 提供用于显示应用版本信息和 Git 信息的 Web 端点。
     * 通过 @WebEndpoint 注解注册为 id 为 "start" 的 Actuator 端点。
     * 支持根据 git.properties 文件的存在情况提供不同的响应。
     *
     * @author dong4j
     * @version 1.0.0
     * @email "mailto:dong4j@gmail.com"
     * @date 2021.12.22 09:31
     * @since 1.0.0
     */
    @WebEndpoint(id = "start")
    public static class StartInfoEndpoint {
        /** HTTP 响应对象，用于重定向 */
        @Resource
        private HttpServletResponse response;

        /**
         * 获取应用版本信息
         * <p>
         * 显示 Git 相关信息，如果本地编译运行没有生成 git.properties 文件，
         * 则直接重定向到 /actuator/info 端点。
         * 如果存在 git.properties 文件，则读取并返回其中的所有属性。
         *
         * @return Git 属性信息或 null（重定向情况下）
         * @throws IOException 文件读取异常
         * @since 1.0.0
         */
        @ReadOperation
        public Result<Properties> versionInformation() throws IOException {
            // 获取类加载器
            ClassLoader classLoader = this.getClass().getClassLoader();
            // 尝试加载 git.properties 文件
            InputStream inputStream = classLoader.getResourceAsStream(App.GIT_CONFIG_FILE_NAME);
            // 如果文件不存在，重定向到 /actuator/info
            if (inputStream == null) {
                this.response.sendRedirect(ConfigKit.getContextPath() + LibraryEnum.START_URL);
                return null;
            } else {
                // 读取 git.properties 文件内容
                Properties properties = new Properties();
                try {
                    properties.load(inputStream);
                } catch (IOException ignored) {
                    // 忽略读取异常
                }
                return R.succeed(properties);
            }
        }
    }

    /**
     * 创建 Servlet 初始化服务
     * <p>
     * 在 Servlet 环境下创建初始化服务实现，用于应用预热。
     * 仅在没有其他 InitializationService 实现时才会创建。
     *
     * @return ServletInitializationService 实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(InitializationService.class)
    public InitializationService servletInitializationService() {
        return new ServletInitializationService();
    }
}

