package dev.dong4j.zeka.starter.messaging.autoconfigure;

import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;
import org.springframework.kafka.config.KafkaListenerEndpointRegistry;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.starter.messaging.factory.DefaultRocketMQContainerRegistry;
import dev.dong4j.zeka.starter.messaging.factory.RocketMQContainerFactoryProxy;
import dev.dong4j.zeka.starter.messaging.registry.MessagingListenerRegistry;
import dev.dong4j.zeka.starter.messaging.registry.MessagingRegistrationHandler;
import dev.dong4j.zeka.starter.messaging.util.MessagingTypeDetector;

/**
 * 消息容器自动配置类
 * <p>
 * 该类负责配置消息监听容器相关的组件，包括：
 * 1. 消息类型检测器
 * 2. Kafka 监听器端点注册表
 * 3. RocketMQ 容器注册器
 * 4. 消息注册处理器
 * 5. 消息监听器注册表
 * <p>
 * 使用场景：
 * 1. 自动配置消息监听容器
 * 2. 集成多种消息中间件(Kafka, RocketMQ)
 * 3. 提供统一的注册管理机制
 * <p>
 * 配置属性前缀：zeka-stack.messaging
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2025.06.27
 * @since 1.0.0
 */
@AutoConfiguration
@ConditionalOnEnabled(value = MessagingProperties.PREFIX)
@EnableConfigurationProperties(MessagingProperties.class)
public class MessagingContainerConfiguration {

    /**
     * 创建消息类型检测器 Bean
     *
     * @param environment Spring 环境对象
     * @return 消息类型检测器实例
     */
    @Bean
    public MessagingTypeDetector messagingTypeDetector(Environment environment) {
        return new MessagingTypeDetector(environment);
    }

    /**
     * 创建 Kafka 监听器端点注册表 Bean
     * <p>
     * 注意：如果 Spring Kafka 已经自动配置了该 Bean，则不会重复创建
     *
     * @return Kafka 监听器端点注册表实例
     */
    @Bean
    @ConditionalOnMissingBean
    public KafkaListenerEndpointRegistry kafkaListenerEndpointRegistry() {
        return new KafkaListenerEndpointRegistry();
    }

    /**
     * 创建 RocketMQ 容器注册器 Bean
     *
     * @return RocketMQ 容器注册器实例
     */
    @Bean
    public RocketMQContainerFactoryProxy.RocketMQContainerRegistry rocketMQContainerRegistry() {
        return new DefaultRocketMQContainerRegistry();
    }

    /**
     * 创建消息注册处理器 Bean
     *
     * @param kafkaRegistry    Kafka 监听器端点注册表
     * @param rocketmqRegistry RocketMQ 容器注册器
     * @return 消息注册处理器实例
     */
    @Bean
    public MessagingRegistrationHandler messagingRegistrationHandler(KafkaListenerEndpointRegistry kafkaRegistry,
                                                                     RocketMQContainerFactoryProxy.RocketMQContainerRegistry rocketmqRegistry) {

        return new MessagingRegistrationHandler(kafkaRegistry, rocketmqRegistry);
    }

    /**
     * 创建消息监听器注册表 Bean
     *
     * @param registrationHandler 消息注册处理器
     * @param typeDetector        消息类型检测器
     * @return 消息监听器注册表实例
     */
    @Bean
    public MessagingListenerRegistry messagingListenerRegistry(MessagingRegistrationHandler registrationHandler,
                                                               MessagingTypeDetector typeDetector) {
        return new MessagingListenerRegistry(registrationHandler, typeDetector);
    }


}

package dev.dong4j.zeka.starter.messaging.autoconfigure;

import org.apache.rocketmq.spring.core.RocketMQTemplate;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.context.annotation.Bean;
import org.springframework.kafka.core.KafkaTemplate;

import java.util.List;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.starter.messaging.enums.MessagingType;
import dev.dong4j.zeka.starter.messaging.template.KafkaMessagingTemplateAdapter;
import dev.dong4j.zeka.starter.messaging.template.RocketMQMessagingTemplateAdapter;
import dev.dong4j.zeka.starter.messaging.template.adapter.MessagingTemplateAdapter;
import dev.dong4j.zeka.starter.messaging.template.core.DefaultMessagingTemplate;

/**
 * 消息模板自动配置类
 * <p>
 * 该类负责配置消息发送模板相关的组件，包括：
 * 1. Kafka 消息模板适配器
 * 2. RocketMQ 消息模板适配器
 * 3. 默认消息模板
 * <p>
 * 配置属性前缀：zeka.messaging
 * <p>
 * 使用场景：
 * 1. 自动配置消息发送模板
 * 2. 集成多种消息中间件(Kafka, RocketMQ)的发送能力
 * 3. 提供统一的消息发送接口
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2025.06.27
 * @since 1.0.0
 */
@AutoConfiguration
@ConditionalOnEnabled(value = MessagingProperties.PREFIX)
public class MessagingTemplateAutoConfiguration {

    /**
     * 创建 Kafka 消息模板适配器
     *
     * @param kafkaTemplate Spring Kafka 模板
     * @return Kafka 消息模板适配器实例
     */
    @Bean
    @ConditionalOnBean(KafkaTemplate.class)
    public MessagingTemplateAdapter kafkaTemplateAdapter(KafkaTemplate<?, ?> kafkaTemplate) {
        // noinspection unchecked
        return new KafkaMessagingTemplateAdapter((KafkaTemplate<String, Object>) kafkaTemplate);
    }

    /**
     * 创建 RocketMQ 消息模板适配器
     *
     * @param rocketMQTemplate RocketMQ 模板
     * @return RocketMQ 消息模板适配器实例
     */
    @Bean
    @ConditionalOnBean(RocketMQTemplate.class)
    public MessagingTemplateAdapter rocketMQTemplateAdapter(RocketMQTemplate rocketMQTemplate) {
        return new RocketMQMessagingTemplateAdapter(rocketMQTemplate);
    }

    /**
     * 创建默认消息模板
     *
     * @param availableAdapters 可用的消息模板适配器列表
     * @return 默认消息模板实例
     */
    @Bean
    public DefaultMessagingTemplate unifiedMessageTemplate(List<MessagingTemplateAdapter> availableAdapters) {
        DefaultMessagingTemplate template = new DefaultMessagingTemplate();

        // 注册所有可用的适配器
        for (MessagingTemplateAdapter adapter : availableAdapters) {
            if (adapter instanceof KafkaMessagingTemplateAdapter) {
                template.registerAdapter(MessagingType.KAFKA, adapter);
            } else if (adapter instanceof RocketMQMessagingTemplateAdapter) {
                template.registerAdapter(MessagingType.ROCKETMQ, adapter);
            }
        }

        return template;
    }
}

