import jakarta.servlet.MultipartConfigElement;
import jakarta.servlet.Servlet;
import lombok.extern.slf4j.Slf4j;

/**
 * Undertow 容器自动配置类
 * <p>
 * 该自动配置类专门用于配置和优化 Undertow Web 服务器。Undertow 是一个高性能的
 * Java Web 服务器，特别适合于微服务和高并发场景。这个配置类提供了 Undertow
 * 容器的各种优化设置和功能增强。
 * <p>
 * 主要功能：
 * 1. WebSocket 支持：解决 WebSocket 缓冲池警告问题
 * 2. HTTP/2 支持：可选择性开启 HTTP/2 协议支持
 * 3. 请求日志：支持详细的 HTTP 请求日志记录
 * 4. 文件上传：配置 multipart 文件上传的临时目录
 * 5. 性能优化：开启请求时间记录，支持访问日志的时间统计
 * <p>
 * 配置特点：
 * - WebSocket 缓冲池：自动配置 DefaultByteBufferPool，避免默认池警告
 * - HTTP/2 协议：通过配置属性控制是否启用
 * - 动态日志：支持运行时开关容器请求日志
 * - 文件上传：自定义临时目录配置
 * - 请求计时：开启 RECORD_REQUEST_START_TIME 支持访问日志中的耗时统计
 * <p>
 * 容器优化：
 * - 解决 UT026010 警告：Buffer pool was not set on WebSocketDeploymentInfo
 * - 支持 HTTP/2 协议，提升传输效率
 * - 提供详细的请求追踪和日志记录
 * - 优化文件上传的临时存储配置
 * <p>
 * 使用场景：
 * - 高并发的 Web 应用
 * - 需要 WebSocket 支持的实时应用
 * - 需要 HTTP/2 支持的现代 Web 应用
 * - 需要详细请求日志的监控场景
 * - 微服务架构中的业务服务
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2019.11.21 21:47
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@EnableConfigurationProperties(RestProperties.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
@ConditionalOnClass(value = {Servlet.class, DispatcherServlet.class, ZekaServletExceptionErrorAttributes.class, Undertow.class})
public class UndertowAutoConfiguration implements ZekaAutoConfiguration, WebServerFactoryCustomizer<UndertowServletWebServerFactory> {

    /** Rest properties */
    private final RestProperties properties;

    /**
     * Undertow 自动配置构造函数
     * <p>
     * 初始化 Undertow 自动配置，接收 REST 配置属性用于后续的容器定制。
     *
     * @param properties REST 模块配置属性，包含 Undertow 相关的配置选项
     * @since 1.0.0
     */
    @Contract(pure = true)
    public UndertowAutoConfiguration(RestProperties properties) {
        this.properties = properties;
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 配置文件上传的临时目录
     * <p>
     * 创建 multipart 文件上传配置，设置 Undertow 容器处理文件上传时的临时存储目录。
     * 这个配置对于文件上传功能的性能和安全性都很重要。
     * <p>
     * 配置作用：
     * - 指定文件上传时的临时存储位置
     * - 避免使用系统默认临时目录可能带来的权限问题
     * - 便于文件上传的监控和管理
     * - 支持大文件上传的磁盘空间规划
     *
     * @return 配置好的 multipart 配置元素
     * @since 1.0.0
     */
    @Bean
    public MultipartConfigElement multipartConfigElement() {
        MultipartConfigFactory factory = new MultipartConfigFactory();
        final String location = this.properties.getMultipart().getLocation();
        log.debug("Undertow 容器目录: [{}]", location);
        factory.setLocation(location);
        return factory.createMultipartConfig();
    }

    /**
     * 自定义 Undertow 服务器配置
     * <p>
     * 这个方法实现了对 Undertow 服务器的深度定制，包括 WebSocket 支持、HTTP/2 支持、
     * 请求日志记录等功能。这些配置主要用于提升服务器性能和增强监控能力。
     * <p>
     * 主要配置项：
     * 1. WebSocket 缓冲池配置：
     * - 解决 UT026010 警告问题
     * - 设置 DefaultByteBufferPool，避免使用默认池
     * - 缓冲区大小设置为 1024 字节
     * <p>
     * 2. HTTP/2 支持：
     * - 根据配置属性决定是否开启
     * - 通过 UndertowOptions.ENABLE_HTTP2 选项控制
     * - 提升 HTTP 传输效率和性能
     * <p>
     * 3. 请求日志功能：
     * - 添加自定义的请求转储处理器
     * - 支持动态开关日志记录
     * - 集成框架的日志显示逻辑
     * <p>
     * 4. 请求计时支持：
     * - 开启 RECORD_REQUEST_START_TIME 选项
     * - 支持访问日志中的 %D 时间统计
     * - 用于性能监控和分析
     *
     * @param factory Undertow Servlet Web 服务器工厂
     * @see AccessLogHandler 访问日志处理器
     * @see RequestDumpingHandler 请求转储处理器
     * @since 1.0.0
     */
    @Override
    public void customize(@NotNull UndertowServletWebServerFactory factory) {
        factory.addDeploymentInfoCustomizers(deploymentInfo -> {
            WebSocketDeploymentInfo webSocketDeploymentInfo = new WebSocketDeploymentInfo();
            webSocketDeploymentInfo.setBuffers(new DefaultByteBufferPool(false, 1024));
            deploymentInfo.addServletContextAttribute("io.undertow.websockets.jsr.WebSocketDeploymentInfo", webSocketDeploymentInfo);
        });

        // 开启 http2 支持
        if (this.properties.isEnableHttp2()) {
            factory.addBuilderCustomizers(builder -> builder.setServerOption(UndertowOptions.ENABLE_HTTP2, true));
        }

        // 开启 http 请求日志
        factory.addDeploymentInfoCustomizers(
            info -> info.addInitialHandlerChainWrapper(
                next -> new CustomRequestDumpingHandler(next, this.properties)));

        // %D 需要开启 undertow 记时 (access.log)
        factory.addBuilderCustomizers(builder -> builder.setServerOption(UndertowOptions.RECORD_REQUEST_START_TIME, true));
    }

    /**
     * 自定义请求转储处理器
     * <p>
     * 这个内部静态类实现了自定义的 HTTP 请求处理逻辑，主要用于在请求处理过程中
     * 根据配置动态决定是否记录详细的请求日志。它包装了下一个处理器，在处理
     * 请求前进行日志记录判断。
     * <p>
     * 设计特点：
     * - 动态日志开关：每次请求都会检查是否需要记录日志
     * - 配置驱动：通过 enableContainerLog 配置控制日志记录
     * - 透明处理：不影响正常的请求处理流程
     * - 性能优化：只在需要时才进行日志处理
     * <p>
     * 日志记录条件：
     * 1. 日志等级必须设置为 trace 级别
     * 2. 必须配置 enable-container-log: true
     * <p>
     * 这种设计允许在运行时动态控制 Undertow 容器的日志输出，
     * 便于生产环境的问题排查和性能调优。
     *
     * @author dong4j
     * @version 1.0.0
     * @email "mailto:dong4j@gmail.com"
     * @date 2021.04.25 19:59
     * @since 1.0.0
     */
    static class CustomRequestDumpingHandler implements HttpHandler {
        /** Properties */
        private final RestProperties properties;
        /** Next */
        private final HttpHandler next;

        /**
         * 自定义请求转储处理器构造函数
         * <p>
         * 初始化请求转储处理器，保存下一个处理器的引用和配置属性。
         *
         * @param next       下一个 HTTP 处理器
         * @param properties REST 配置属性，包含日志开关等配置
         * @since 1.0.0
         */
        CustomRequestDumpingHandler(HttpHandler next, RestProperties properties) {
            this.next = next;
            this.properties = properties;
        }

        /**
         * 处理 HTTP 请求
         * <p>
         * 每次请求都会判断是否需要输出日志，实现动态开关功能。
         * 这个方法在每个 HTTP 请求到达时被调用，根据配置决定是否记录请求详情。
         * <p>
         * 处理流程：
         * 1. 检查日志配置和级别
         * 2. 如果满足条件，记录请求详细信息
         * 3. 将请求传递给下一个处理器继续处理
         * <p>
         * 日志记录条件：
         * 1. 日志等级必须设置为 trace 级别
         * 2. 必须配置 enable-container-log: true
         *
         * @param exchange HTTP 服务器交换对象，包含请求和响应信息
         * @throws Exception 请求处理过程中可能抛出的异常
         * @since 1.0.0
         */
        @Override
        public void handleRequest(HttpServerExchange exchange) throws Exception {
            ShowUndertowLog.showLog(exchange, this.properties.isEnableContainerLog());
            // Perform the exchange
            this.next.handleRequest(exchange);
        }
    }

}

package dev.dong4j.zeka.starter.rest.autoconfigure.supportss;

import com.fasterxml.jackson.databind.ObjectMapper;

import org.jetbrains.annotations.NotNull;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.jackson.JacksonAutoConfiguration;
import org.springframework.boot.autoconfigure.jackson.JacksonProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.util.Jsons;
import dev.dong4j.zeka.kernel.web.jackson.JavaTimeModule;
import dev.dong4j.zeka.starter.rest.autoconfigure.RestProperties;
import lombok.extern.slf4j.Slf4j;

/**
 * Jackson JSON 序列化配置类
 * <p>
 * 该配置类专门用于自定义和优化 Jackson ObjectMapper 的配置。
 * Jackson 是 Spring Boot 中默认的 JSON 序列化库，负责处理 HTTP 请求和响应
 * 中的 JSON 数据转换。这个配置类提供了统一的 JSON 处理策略。
 * <p>
 * 主要功能：
 * 1. 提供全局统一的 ObjectMapper 实例
 * 2. 集成 JDK 8 的日期时间 API 支持
 * 3. 自动配置序列化包含策略
 * 4. 支持自定义的 Jackson 模块注册
 * 5. 与 Spring Boot 的 Jackson 配置系统集成
 * <p>
 * 配置特点：
 * - 基于框架的全局 ObjectMapper 副本，保持一致性
 * - 支持 JDK 8 的 LocalDateTime、LocalDate 等新时间 API
 * - 遵循 Spring Boot 的 JacksonProperties 配置
 * - 自动注册和发现 Jackson 模块
 * - 使用 @Primary 注解确保优先级
 * <p>
 * 加载顺序：
 * 通过 @AutoConfiguration(before = JacksonAutoConfiguration.class) 确保
 * 在 Spring Boot 的 JacksonAutoConfiguration 之前加载，保证自定义配置的优先级。
 * <p>
 * 配置集成：
 * - JacksonProperties：读取 Spring Boot 的 Jackson 配置属性
 * - JavaTimeModule：支持 JDK 8 时间 API 的序列化
 * - Jsons.getCopyMapper()：获取框架的全局 ObjectMapper 副本
 * <p>
 * 使用场景：
 * - REST API 的 JSON 响应序列化
 * - HTTP 请求体的 JSON 反序列化
 * - 微服务间的 JSON 数据交换
 * - 数据库存储的 JSON 字段处理
 * - 缓存数据的序列化存储
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.01.27 14:53
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration(before = JacksonAutoConfiguration.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnClass(value = {ObjectMapper.class})
@EnableConfigurationProperties(JacksonProperties.class)
public class JacksonConfiguration implements ZekaAutoConfiguration {
    /** Jackson properties */
    private JacksonProperties jacksonProperties;

    /**
     * Jackson 配置类构造函数
     * <p>
     * 初始化 Jackson 配置，并从 Spring Boot 的配置系统中获取 JacksonProperties。
     * 使用 ObjectProvider 进行延迟注入，避免循环依赖问题。
     *
     * @param jacksonPropertiesObjectProvider Jackson 属性对象提供者，用于获取 Spring Boot 的 Jackson 配置
     * @since 1.0.0
     */
    public JacksonConfiguration(@NotNull ObjectProvider<JacksonProperties> jacksonPropertiesObjectProvider) {
        log.info("启动自动配置: [{}]", this.getClass());
        if (jacksonPropertiesObjectProvider.getIfAvailable() != null) {
            this.jacksonProperties = jacksonPropertiesObjectProvider.getIfAvailable();
        }
    }

    /**
     * 创建自定义的 Jackson ObjectMapper
     * <p>
     * 该方法创建了一个全局使用的 ObjectMapper 实例，集成了框架的默认配置
     * 和自定义的功能增强。这个 ObjectMapper 会被 Spring 容器管理，
     * 并作为主要的 JSON 序列化工具在整个应用中使用。
     * <p>
     * 配置内容：
     * 1. 基础配置：
     * - 使用 Jsons.getCopyMapper() 获取框架的全局 ObjectMapper 副本
     * - 保持与框架其他组件的一致性
     * <p>
     * 2. 序列化包含策略：
     * - 读取 JacksonProperties 中的 defaultPropertyInclusion 配置
     * - 控制哪些字段参与 JSON 序列化（如排除 null 值字段）
     * <p>
     * 3. JDK 8 时间 API 支持：
     * - 注册 JavaTimeModule 模块
     * - 支持 LocalDateTime、LocalDate、Instant 等新时间类型
     * - 提供统一的日期时间序列化格式
     * <p>
     * 4. 模块自动发现：
     * - 调用 findAndRegisterModules() 自动注册类路径下的 Jackson 模块
     * - 支持第三方库的 Jackson 扩展
     * <p>
     * 注解说明：
     * - @Bean：将返回的 ObjectMapper 注册为 Spring Bean
     * - @Primary：设置为主要的 ObjectMapper，在多个候选者中优先使用
     *
     * @return 配置完成的 Jackson ObjectMapper 实例
     * @since 1.0.0
     */
    @Bean
    @Primary
    public ObjectMapper jacksonObjectMapper() {
        ObjectMapper globalObjectMapper = Jsons.getCopyMapper();
        if (this.jacksonProperties.getDefaultPropertyInclusion() != null) {
            globalObjectMapper.setSerializationInclusion(this.jacksonProperties.getDefaultPropertyInclusion());
        }
        // 添加 JDK8 的时间转换器
        globalObjectMapper.registerModule(new JavaTimeModule());
        globalObjectMapper.findAndRegisterModules();
        log.debug("初始化自定义 Jackson 配置 [{}]", globalObjectMapper);
        return globalObjectMapper;
    }

}

