/**
 * Servlet Web 环境自动配置类
 * <p>
 * 该自动配置类是 Servlet Web 环境下的核心配置组件，负责配置和注册
 * 所有与 Web 请求处理相关的组件。它提供了完整的 Web 层基础设施配置，
 * 包括消息转换器、过滤器、拦截器、参数解析器等。
 * <p>
 * 主要功能：
 * 1. HTTP 消息转换器配置：使用 Jackson 作为 JSON 转换器，支持枚举序列化
 * 2. 跨域请求支持：非生产环境自动开启 CORS 支持
 * 3. 字符编码过滤器：统一设置 UTF-8 编码
 * 4. 全局缓存过滤器：缓存 Request 和 Response 以支持重复读取
 * 5. 异常处理过滤器：在 Filter 层提供异常捕获和处理
 * 6. XSS 防护过滤器：防止跨站脚本攻击
 * 7. 参数注入过滤器：支持全局参数注入机制
 * 8. 自定义参数解析器：支持多种自定义注解的参数解析
 * 9. 拦截器注册：用户认证、链路追踪等拦截器
 * 10. API 版本控制：支持基于 URL 的 API 版本管理
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2019.11.21 21:47
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration(after = JacksonConfiguration.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@EnableConfigurationProperties(value = {ServerProperties.class, XssProperties.class, WebProperties.class})
@ConditionalOnClass(value = {Servlet.class, DispatcherServlet.class, ZekaServletExceptionErrorAttributes.class})
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
public class ServletWebAutoConfiguration implements WebMvcConfigurer, ZekaAutoConfiguration {

    /** Object mapper */
    @Resource
    private ObjectMapper objectMapper;
    /** Current user argument resolver */
    @Resource
    private CurrentUserArgumentResolver currentUserArgumentResolver;
    /** Current user interceptor */
    @Resource
    private CurrentUserInterceptor currentUserInterceptor;
    /** Authentication interceptor */
    @Resource
    private AuthenticationInterceptor authenticationInterceptor;
    /** GLOBAL_ENUM_CONVERTER_FACTORY */
    private static final ConverterFactory<String, SerializeEnum<?>> GLOBAL_ENUM_CONVERTER_FACTORY = new GlobalEnumConverterFactory();
    /** MAX_AGE */
    private static final Long MAX_AGE = 18000L;

    /**
     * 构造函数，初始化 Servlet Web 自动配置
     *
     * @since 1.0.0
     */
    public ServletWebAutoConfiguration() {
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 注册字符编码过滤器
     * <p>
     * 设置字符过滤器，强制设置请求和响应的字符编码为 UTF-8。
     * 这确保了整个应用在处理中文等多字节字符时的一致性和正确性。
     *
     * @return 配置好的字符编码过滤器注册Bean
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(CharacterEncodingFilter.class)
    public FilterRegistrationBean<CharacterEncodingFilter> characterEncodingFilterFilterRegistrationBean() {
        FilterRegistrationBean<CharacterEncodingFilter> registrationBean = new FilterRegistrationBean<>();
        CharacterEncodingFilter characterEncodingFilter = new CharacterEncodingFilter();
        characterEncodingFilter.setEncoding(StringPool.UTF_8);
        characterEncodingFilter.setForceEncoding(true);
        registrationBean.setFilter(characterEncodingFilter);
        return registrationBean;
    }

    /**
     * 注册全局缓存过滤器
     * <p>
     * request 和 response 缓存过滤器，用于缓存 HTTP 请求和响应的内容，
     * 允许在请求处理过程中多次读取请求体和响应体。
     *
     * @param properties Web 配置属性，包含缓存忽略的 URL 模式等配置
     * @return 配置好的全局缓存过滤器注册Bean
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(ServletGlobalCacheFilter.class)
    @ConditionalOnProperty(
        value = ConfigKey.WEB_ENABLE_GLOBAL_CACHE_FILTER,
        havingValue = ConfigDefaultValue.TRUE_STRING,
        matchIfMissing = true
    )
    public FilterRegistrationBean<ServletGlobalCacheFilter> servletGlobalCacheFilterFilterRegistrationBean(
        @NotNull WebProperties properties) {
        log.debug("加载 Request & Response Cahce 过滤器 [{}]", ServletGlobalCacheFilter.class);
        ServletGlobalCacheFilter servletGlobalCacheFilter = new ServletGlobalCacheFilter(properties.getIgnoreCacheRequestUrl());
        FilterRegistrationBean<ServletGlobalCacheFilter> bean = new FilterRegistrationBean<>(servletGlobalCacheFilter);
        InnerWebUtils.setUrlPatterns(bean, Ordered.HIGHEST_PRECEDENCE);
        return bean;
    }

    /**
     * 注册跨域请求过滤器
     * <p>
     * 跨域 CORS 配置，不是 prod 环境才允许跨域。
     * 在非生产环境下注册 CORS 过滤器，允许前端应用从不同域名访问后端 API。
     *
     * @return 配置好的CORS过滤器注册Bean
     * @since 1.0.0
     */
    @Bean
    @Profile(value = {App.ENV_NOT_PROD})
    @ConditionalOnMissingBean(CorsFilter.class)
    public FilterRegistrationBean<CorsFilter> corsFilterFilterRegistrationBean() {
        log.debug("非正式环境开启跨域支持: {}", CorsFilter.class);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration(StringPool.ANY_PATH, this.buildConfig());
        CorsFilter corsFilter = new CorsFilter(source);
        FilterRegistrationBean<CorsFilter> bean = new FilterRegistrationBean<>(corsFilter);
        InnerWebUtils.setUrlPatterns(bean, Ordered.HIGHEST_PRECEDENCE + 40);
        return bean;
    }

    /**
     * 注册过滤器异常处理器
     * <p>
     * Filter 异常处理器，用于捕获和处理过滤器层异常。
     * 当在过滤器链中发生异常时，该过滤器会统一处理这些异常。
     *
     * @param serverProperties 服务器配置属性，包含错误页面路径等配置
     * @return 配置好的异常过滤器注册Bean
     * @see ExceptionFilter 过滤器异常处理器实现
     * @see ServletErrorController 错误控制器
     * @see RestProperties#isEnableExceptionFilter 异常过滤器开关配置
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(ExceptionFilter.class)
    @ConditionalOnProperty(
        value = ConfigKey.WEB_ENABLE_EXCEPTION_FILTER,
        havingValue = ConfigDefaultValue.TRUE_STRING,
        matchIfMissing = true
    )
    public FilterRegistrationBean<ExceptionFilter> exceptionFilterFilterRegistrationBean(ServerProperties serverProperties) {
        log.debug("加载 Filter 异常处理器 [{}]", ExceptionFilter.class);
        FilterRegistrationBean<ExceptionFilter> bean = new FilterRegistrationBean<>(new ExceptionFilter(serverProperties));
        InnerWebUtils.setUrlPatterns(bean, Ordered.HIGHEST_PRECEDENCE + 50);
        return bean;
    }

    /**
     * 注册全局参数注入过滤器
     * <p>
     * 参数注入过滤器，用于在请求处理过程中自动注入一些全局性的参数。
     *
     * @return 配置好的全局参数注入过滤器注册Bean
     * @see RestProperties#isEnableGlobalParameterFilter 全局参数注入过滤器开关配置
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(GlobalParameterFilter.class)
    @ConditionalOnProperty(
        value = ConfigKey.REST_ENABLE_GLOBAL_PARAMETER_FILTER,
        havingValue = ConfigDefaultValue.TRUE_STRING,
        matchIfMissing = true
    )
    public FilterRegistrationBean<GlobalParameterFilter> globalParameterFilterFilterRegistrationBean() {
        log.info("加载全局参数注入拦截器: {}", GlobalParameterFilter.class);
        FilterRegistrationBean<GlobalParameterFilter> bean = new FilterRegistrationBean<>(new GlobalParameterFilter());
        InnerWebUtils.setUrlPatterns(bean, Ordered.LOWEST_PRECEDENCE - 1000);
        return bean;
    }

    /**
     * 注册 XSS 防护过滤器
     * <p>
     * 防 XSS 注入 Filter，用于防止跨站脚本攻击。
     * 该过滤器会对请求参数进行安全过滤，移除或转义潜在的恶意脚本代码。
     *
     * @param xssProperties XSS 防护配置属性，包含排除模式等配置
     * @return 配置好的XSS防护过滤器注册Bean
     * @see XssProperties#isEnableXssFilter XSS过滤器开关配置
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(XssFilter.class)
    @ConditionalOnProperty(
        value = ConfigKey.XSS_ENABLE_XSS_FILTER,
        havingValue = ConfigDefaultValue.TRUE_STRING,
        matchIfMissing = true
    )
    public FilterRegistrationBean<XssFilter> xssFilterFilterRegistrationBean(XssProperties xssProperties) {
        log.debug("加载防 XSS 注入 Filter: {}", XssFilter.class);
        FilterRegistrationBean<XssFilter> bean = new FilterRegistrationBean<>(new XssFilter(xssProperties.getExcludePatterns()));
        InnerWebUtils.setUrlPatterns(bean, Ordered.LOWEST_PRECEDENCE - 900);
        return bean;
    }

    /**
     * 注册自定义格式化器和转换器
     * <p>
     * 前端传入的时间字符串，自动转换为 Date 类型，只针对普通的字段。
     * 如果是 @RequestBody 中的字段，将使用 {@link MappingApiJackson2HttpMessageConverter} 使用 jackson 进行转换。
     *
     * @param registry Spring MVC 的格式化注册表
     * @since 1.0.0
     */
    @Override
    public void addFormatters(@NotNull FormatterRegistry registry) {
        log.debug("注册 String -> Date 转换器 :[{}] 格式: [{}]", StringToDateConverter.class, StringToDateConverter.PATTERN);
        registry.addConverter(new StringToDateConverter());
        log.debug("注册通用枚举转换器: [{}]", GlobalEnumConverterFactory.class);
        registry.addConverterFactory(GLOBAL_ENUM_CONVERTER_FACTORY);
        log.debug("注册 String -> Map 转换器 :[{}]", StringToMapConverter.class);
        registry.addConverter(new StringToMapConverter());
    }

    /**
     * 注册自定义参数解析器
     * <p>
     * 向 Spring MVC 添加自定义的方法参数解析器，用于处理 Controller 方法中的特殊注解参数。
     *
     * @param argumentResolvers Spring MVC 的参数解析器列表
     * @since 1.0.0
     */
    @Override
    public void addArgumentResolvers(@NotNull List<HandlerMethodArgumentResolver> argumentResolvers) {
        log.debug("注册 @RequestSingleParam 注解处理器: [{}]", RequestSingleParamHandlerMethodArgumentResolver.class);
        argumentResolvers.add(new RequestSingleParamHandlerMethodArgumentResolver(this.objectMapper, GLOBAL_ENUM_CONVERTER_FACTORY));
        argumentResolvers.add(new RequestAbstractFormMethodArgumentResolver(this.objectMapper, GLOBAL_ENUM_CONVERTER_FACTORY));
        argumentResolvers.add(new FormdataBodyArgumentResolver(this.objectMapper, GLOBAL_ENUM_CONVERTER_FACTORY));
        argumentResolvers.add(this.currentUserArgumentResolver);
    }

    /**
     * 配置 HTTP 消息转换器
     * <p>
     * 使用 JACKSON 作为 JSON MessageConverter，配置 Spring MVC 的 HTTP 消息转换器。
     *
     * @param converters Spring MVC 的消息转换器列表
     * @since 1.0.0
     */
    @Override
    public void configureMessageConverters(@NotNull List<HttpMessageConverter<?>> converters) {
        log.debug("加载自定义消息增强转换器 [{}]", MappingApiJackson2HttpMessageConverter.class);
        converters.removeIf(x -> x instanceof StringHttpMessageConverter || x instanceof AbstractJackson2HttpMessageConverter);
        // Content-Type = text/plain 消息转换器, 强制使用 UTF-8
        converters.add(new StringHttpMessageConverter(Charsets.UTF_8));
        converters.add(new ByteArrayHttpMessageConverter());
        converters.add(new BufferedImageHttpMessageConverter());
        converters.add(new ResourceHttpMessageConverter());
        converters.add(new ResourceRegionHttpMessageConverter());

        this.config();

        converters.add(new MappingApiJackson2HttpMessageConverter(this.objectMapper));
    }

    /**
     * 配置自定义枚举序列化与反序列化
     * <p>
     * 为 ObjectMapper 注册自定义的枚举序列化器和反序列化器。
     *
     * @since 1.0.0
     */
    private void config() {
        log.debug("加载枚举自定义序列化/反序列化处理器: [{}] [{}]", EntityEnumSerializer.class, EntityEnumDeserializer.class);
        SimpleModule simpleModule = new SimpleModule("EntityEnum-Converter", PackageVersion.VERSION);
        simpleModule.addDeserializer(SerializeEnum.class, new EntityEnumDeserializer<>());
        simpleModule.addSerializer(SerializeEnum.class, new EntityEnumSerializer<>());
        this.objectMapper.registerModule(simpleModule);
        this.objectMapper.findAndRegisterModules();
    }

    /**
     * 注册拦截器
     * <p>
     * 添加拦截器，包括当前用户拦截器和认证拦截器。
     *
     * @param registry 拦截器注册表
     * @since 1.0.0
     */
    @Override
    public void addInterceptors(@NotNull InterceptorRegistry registry) {
        log.debug("加载响应结果包装拦截器: [{}]", CurrentUserInterceptor.class);

        registry.addInterceptor(this.currentUserInterceptor)
            .addPathPatterns(StringPool.ANY_PATH)
            .excludePathPatterns(new ArrayList<>(SecurityUtils.mergeSkipPatterns("")));

        log.debug("加载响应结果包装拦截器: [{}]", AuthenticationInterceptor.class);
        registry.addInterceptor(this.authenticationInterceptor)
            .addPathPatterns(StringPool.ANY_PATH)
            .excludePathPatterns(new ArrayList<>(SecurityUtils.mergeSkipPatterns("")));

    }

    /**
     * 配置路径匹配
     * <p>
     * 开启矩阵变量 {@code @MatrixVariable} 支持。
     *
     * @param configurer 路径匹配配置器
     * @since 1.0.0
     */
    @Override
    public void configurePathMatch(@NotNull PathMatchConfigurer configurer) {
        UrlPathHelper urlPathHelper = new UrlPathHelper();
        urlPathHelper.setRemoveSemicolonContent(false);
        configurer.setUrlPathHelper(urlPathHelper);
    }

    /**
     * 注册 Web MVC 配置
     * <p>
     * 注册 RequestMappingHandlerMapping，不使用继承 WebMvcConfigurationSupport。
     * 替换后，会将其提供的一系列默认组件全部移除。
     *
     * @return Web MVC 注册配置
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(WebMvcRegistrations.class)
    public WebMvcRegistrations registrations() {
        return new WebMvcRegistrations() {
            /**
             * 注册请求映射处理器
             * 注册 RequestMappingHandlerMapping。
             *
             * @return 请求映射处理器
             * @since 1.0.0
             */
            @Override
            public RequestMappingHandlerMapping getRequestMappingHandlerMapping() {
                return new ApiVersionRequestMappingHandlerMapping();
            }
        };
    }


    /**
     * 构建 CORS 配置
     * <p>
     * 构建跨域资源共享配置。
     *
     * @return CORS 配置
     * @since 1.0.0
     */
    private @NotNull CorsConfiguration buildConfig() {
        CorsConfiguration corsConfiguration = new CorsConfiguration();
        // 1. 允许任何域名使用
        corsConfiguration.setAllowedOriginPatterns(Collections.singletonList(StringPool.ASTERISK));
        // 2. 允许任何头
        corsConfiguration.addAllowedHeader(StringPool.ASTERISK);
        // 3. 允许任何方法 (post、get等)
        corsConfiguration.addAllowedMethod(StringPool.ASTERISK);
        corsConfiguration.setMaxAge(MAX_AGE);
        corsConfiguration.setAllowCredentials(true);
        return corsConfiguration;
    }

}

package dev.dong4j.zeka.starter.rest.autoconfigure.servlet;

import org.jetbrains.annotations.Contract;
import org.jetbrains.annotations.NotNull;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.boot.web.embedded.undertow.UndertowServletWebServerFactory;
import org.springframework.boot.web.server.WebServerFactoryCustomizer;
import org.springframework.boot.web.servlet.MultipartConfigFactory;
import org.springframework.context.annotation.Bean;
import org.springframework.web.servlet.DispatcherServlet;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.undertow.ShowUndertowLog;
import dev.dong4j.zeka.starter.rest.autoconfigure.RestProperties;
import dev.dong4j.zeka.starter.rest.handler.ZekaServletExceptionErrorAttributes;
import io.undertow.Undertow;
import io.undertow.UndertowOptions;
import io.undertow.server.DefaultByteBufferPool;
import io.undertow.server.HttpHandler;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.handlers.RequestDumpingHandler;
import io.undertow.server.handlers.accesslog.AccessLogHandler;
import io.undertow.websockets.jsr.WebSocketDeploymentInfo;
import jakarta.servlet.MultipartConfigElement;
import jakarta.servlet.Servlet;
import lombok.extern.slf4j.Slf4j;

/**
 * Undertow 容器自动配置类
 * <p>
 * 该自动配置类专门用于配置和优化 Undertow Web 服务器。Undertow 是一个高性能的
 * Java Web 服务器，特别适合于微服务和高并发场景。这个配置类提供了 Undertow
 * 容器的各种优化设置和功能增强。
 * <p>
 * 主要功能：
 * 1. WebSocket 支持：解决 WebSocket 缓冲池警告问题
 * 2. HTTP/2 支持：可选择性开启 HTTP/2 协议支持
 * 3. 请求日志：支持详细的 HTTP 请求日志记录
 * 4. 文件上传：配置 multipart 文件上传的临时目录
 * 5. 性能优化：开启请求时间记录，支持访问日志的时间统计
 * <p>
 * 配置特点：
 * - WebSocket 缓冲池：自动配置 DefaultByteBufferPool，避免默认池警告
 * - HTTP/2 协议：通过配置属性控制是否启用
 * - 动态日志：支持运行时开关容器请求日志
 * - 文件上传：自定义临时目录配置
 * - 请求计时：开启 RECORD_REQUEST_START_TIME 支持访问日志中的耗时统计
 * <p>
 * 容器优化：
 * - 解决 UT026010 警告：Buffer pool was not set on WebSocketDeploymentInfo
 * - 支持 HTTP/2 协议，提升传输效率
 * - 提供详细的请求追踪和日志记录
 * - 优化文件上传的临时存储配置
 * <p>
 * 使用场景：
 * - 高并发的 Web 应用
 * - 需要 WebSocket 支持的实时应用
 * - 需要 HTTP/2 支持的现代 Web 应用
 * - 需要详细请求日志的监控场景
 * - 微服务架构中的业务服务
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2019.11.21 21:47
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@EnableConfigurationProperties(RestProperties.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
@ConditionalOnClass(value = {Servlet.class, DispatcherServlet.class, ZekaServletExceptionErrorAttributes.class, Undertow.class})
public class UndertowAutoConfiguration implements ZekaAutoConfiguration, WebServerFactoryCustomizer<UndertowServletWebServerFactory> {

    /** Rest properties */
    private final RestProperties properties;

    /**
     * Undertow 自动配置构造函数
     * <p>
     * 初始化 Undertow 自动配置，接收 REST 配置属性用于后续的容器定制。
     *
     * @param properties REST 模块配置属性，包含 Undertow 相关的配置选项
     * @since 1.0.0
     */
    @Contract(pure = true)
    public UndertowAutoConfiguration(RestProperties properties) {
        this.properties = properties;
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 配置文件上传的临时目录
     * <p>
     * 创建 multipart 文件上传配置，设置 Undertow 容器处理文件上传时的临时存储目录。
     * 这个配置对于文件上传功能的性能和安全性都很重要。
     * <p>
     * 配置作用：
     * - 指定文件上传时的临时存储位置
     * - 避免使用系统默认临时目录可能带来的权限问题
     * - 便于文件上传的监控和管理
     * - 支持大文件上传的磁盘空间规划
     *
     * @return 配置好的 multipart 配置元素
     * @since 1.0.0
     */
    @Bean
    public MultipartConfigElement multipartConfigElement() {
        MultipartConfigFactory factory = new MultipartConfigFactory();
        final String location = this.properties.getMultipart().getLocation();
        log.debug("Undertow 容器目录: [{}]", location);
        factory.setLocation(location);
        return factory.createMultipartConfig();
    }

    /**
     * 自定义 Undertow 服务器配置
     * <p>
     * 这个方法实现了对 Undertow 服务器的深度定制，包括 WebSocket 支持、HTTP/2 支持、
     * 请求日志记录等功能。这些配置主要用于提升服务器性能和增强监控能力。
     * <p>
     * 主要配置项：
     * 1. WebSocket 缓冲池配置：
     * - 解决 UT026010 警告问题
     * - 设置 DefaultByteBufferPool，避免使用默认池
     * - 缓冲区大小设置为 1024 字节
     * <p>
     * 2. HTTP/2 支持：
     * - 根据配置属性决定是否开启
     * - 通过 UndertowOptions.ENABLE_HTTP2 选项控制
     * - 提升 HTTP 传输效率和性能
     * <p>
     * 3. 请求日志功能：
     * - 添加自定义的请求转储处理器
     * - 支持动态开关日志记录
     * - 集成框架的日志显示逻辑
     * <p>
     * 4. 请求计时支持：
     * - 开启 RECORD_REQUEST_START_TIME 选项
     * - 支持访问日志中的 %D 时间统计
     * - 用于性能监控和分析
     *
     * @param factory Undertow Servlet Web 服务器工厂
     * @see AccessLogHandler 访问日志处理器
     * @see RequestDumpingHandler 请求转储处理器
     * @since 1.0.0
     */
    @Override
    public void customize(@NotNull UndertowServletWebServerFactory factory) {
        factory.addDeploymentInfoCustomizers(deploymentInfo -> {
            WebSocketDeploymentInfo webSocketDeploymentInfo = new WebSocketDeploymentInfo();
            webSocketDeploymentInfo.setBuffers(new DefaultByteBufferPool(false, 1024));
            deploymentInfo.addServletContextAttribute("io.undertow.websockets.jsr.WebSocketDeploymentInfo", webSocketDeploymentInfo);
        });

        // 开启 http2 支持
        if (this.properties.isEnableHttp2()) {
            factory.addBuilderCustomizers(builder -> builder.setServerOption(UndertowOptions.ENABLE_HTTP2, true));
        }

        // 开启 http 请求日志
        factory.addDeploymentInfoCustomizers(
            info -> info.addInitialHandlerChainWrapper(
                next -> new CustomRequestDumpingHandler(next, this.properties)));

        // %D 需要开启 undertow 记时 (access.log)
        factory.addBuilderCustomizers(builder -> builder.setServerOption(UndertowOptions.RECORD_REQUEST_START_TIME, true));
    }

    /**
     * 自定义请求转储处理器
     * <p>
     * 这个内部静态类实现了自定义的 HTTP 请求处理逻辑，主要用于在请求处理过程中
     * 根据配置动态决定是否记录详细的请求日志。它包装了下一个处理器，在处理
     * 请求前进行日志记录判断。
     * <p>
     * 设计特点：
     * - 动态日志开关：每次请求都会检查是否需要记录日志
     * - 配置驱动：通过 enableContainerLog 配置控制日志记录
     * - 透明处理：不影响正常的请求处理流程
     * - 性能优化：只在需要时才进行日志处理
     * <p>
     * 日志记录条件：
     * 1. 日志等级必须设置为 trace 级别
     * 2. 必须配置 enable-container-log: true
     * <p>
     * 这种设计允许在运行时动态控制 Undertow 容器的日志输出，
     * 便于生产环境的问题排查和性能调优。
     *
     * @author dong4j
     * @version 1.0.0
     * @email "mailto:dong4j@gmail.com"
     * @date 2021.04.25 19:59
     * @since 1.0.0
     */
    static class CustomRequestDumpingHandler implements HttpHandler {
        /** Properties */
        private final RestProperties properties;
        /** Next */
        private final HttpHandler next;

        /**
         * 自定义请求转储处理器构造函数
         * <p>
         * 初始化请求转储处理器，保存下一个处理器的引用和配置属性。
         *
         * @param next       下一个 HTTP 处理器
         * @param properties REST 配置属性，包含日志开关等配置
         * @since 1.0.0
         */
        CustomRequestDumpingHandler(HttpHandler next, RestProperties properties) {
            this.next = next;
            this.properties = properties;
        }

        /**
         * 处理 HTTP 请求
         * <p>
         * 每次请求都会判断是否需要输出日志，实现动态开关功能。
         * 这个方法在每个 HTTP 请求到达时被调用，根据配置决定是否记录请求详情。
         * <p>
         * 处理流程：
         * 1. 检查日志配置和级别
         * 2. 如果满足条件，记录请求详细信息
         * 3. 将请求传递给下一个处理器继续处理
         * <p>
         * 日志记录条件：
         * 1. 日志等级必须设置为 trace 级别
         * 2. 必须配置 enable-container-log: true
         *
         * @param exchange HTTP 服务器交换对象，包含请求和响应信息
         * @throws Exception 请求处理过程中可能抛出的异常
         * @since 1.0.0
         */
        @Override
        public void handleRequest(HttpServerExchange exchange) throws Exception {
            ShowUndertowLog.showLog(exchange, this.properties.isEnableContainerLog());
            // Perform the exchange
            this.next.handleRequest(exchange);
        }
    }

}

package dev.dong4j.zeka.starter.rest.autoconfigure.supportss;

import com.fasterxml.jackson.databind.ObjectMapper;

import org.jetbrains.annotations.NotNull;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.jackson.JacksonAutoConfiguration;
import org.springframework.boot.autoconfigure.jackson.JacksonProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.util.Jsons;
import dev.dong4j.zeka.kernel.web.jackson.JavaTimeModule;
import dev.dong4j.zeka.starter.rest.autoconfigure.RestProperties;
import lombok.extern.slf4j.Slf4j;

/**
 * Jackson JSON 序列化配置类
 * <p>
 * 该配置类专门用于自定义和优化 Jackson ObjectMapper 的配置。
 * Jackson 是 Spring Boot 中默认的 JSON 序列化库，负责处理 HTTP 请求和响应
 * 中的 JSON 数据转换。这个配置类提供了统一的 JSON 处理策略。
 * <p>
 * 主要功能：
 * 1. 提供全局统一的 ObjectMapper 实例
 * 2. 集成 JDK 8 的日期时间 API 支持
 * 3. 自动配置序列化包含策略
 * 4. 支持自定义的 Jackson 模块注册
 * 5. 与 Spring Boot 的 Jackson 配置系统集成
 * <p>
 * 配置特点：
 * - 基于框架的全局 ObjectMapper 副本，保持一致性
 * - 支持 JDK 8 的 LocalDateTime、LocalDate 等新时间 API
 * - 遵循 Spring Boot 的 JacksonProperties 配置
 * - 自动注册和发现 Jackson 模块
 * - 使用 @Primary 注解确保优先级
 * <p>
 * 加载顺序：
 * 通过 @AutoConfiguration(before = JacksonAutoConfiguration.class) 确保
 * 在 Spring Boot 的 JacksonAutoConfiguration 之前加载，保证自定义配置的优先级。
 * <p>
 * 配置集成：
 * - JacksonProperties：读取 Spring Boot 的 Jackson 配置属性
 * - JavaTimeModule：支持 JDK 8 时间 API 的序列化
 * - Jsons.getCopyMapper()：获取框架的全局 ObjectMapper 副本
 * <p>
 * 使用场景：
 * - REST API 的 JSON 响应序列化
 * - HTTP 请求体的 JSON 反序列化
 * - 微服务间的 JSON 数据交换
 * - 数据库存储的 JSON 字段处理
 * - 缓存数据的序列化存储
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.01.27 14:53
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration(before = JacksonAutoConfiguration.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnClass(value = {ObjectMapper.class})
@EnableConfigurationProperties(JacksonProperties.class)
public class JacksonConfiguration implements ZekaAutoConfiguration {
    /** Jackson properties */
    private JacksonProperties jacksonProperties;

    /**
     * Jackson 配置类构造函数
     * <p>
     * 初始化 Jackson 配置，并从 Spring Boot 的配置系统中获取 JacksonProperties。
     * 使用 ObjectProvider 进行延迟注入，避免循环依赖问题。
     *
     * @param jacksonPropertiesObjectProvider Jackson 属性对象提供者，用于获取 Spring Boot 的 Jackson 配置
     * @since 1.0.0
     */
    public JacksonConfiguration(@NotNull ObjectProvider<JacksonProperties> jacksonPropertiesObjectProvider) {
        log.info("启动自动配置: [{}]", this.getClass());
        if (jacksonPropertiesObjectProvider.getIfAvailable() != null) {
            this.jacksonProperties = jacksonPropertiesObjectProvider.getIfAvailable();
        }
    }

    /**
     * 创建自定义的 Jackson ObjectMapper
     * <p>
     * 该方法创建了一个全局使用的 ObjectMapper 实例，集成了框架的默认配置
     * 和自定义的功能增强。这个 ObjectMapper 会被 Spring 容器管理，
     * 并作为主要的 JSON 序列化工具在整个应用中使用。
     * <p>
     * 配置内容：
     * 1. 基础配置：
     * - 使用 Jsons.getCopyMapper() 获取框架的全局 ObjectMapper 副本
     * - 保持与框架其他组件的一致性
     * <p>
     * 2. 序列化包含策略：
     * - 读取 JacksonProperties 中的 defaultPropertyInclusion 配置
     * - 控制哪些字段参与 JSON 序列化（如排除 null 值字段）
     * <p>
     * 3. JDK 8 时间 API 支持：
     * - 注册 JavaTimeModule 模块
     * - 支持 LocalDateTime、LocalDate、Instant 等新时间类型
     * - 提供统一的日期时间序列化格式
     * <p>
     * 4. 模块自动发现：
     * - 调用 findAndRegisterModules() 自动注册类路径下的 Jackson 模块
     * - 支持第三方库的 Jackson 扩展
     * <p>
     * 注解说明：
     * - @Bean：将返回的 ObjectMapper 注册为 Spring Bean
     * - @Primary：设置为主要的 ObjectMapper，在多个候选者中优先使用
     *
     * @return 配置完成的 Jackson ObjectMapper 实例
     * @since 1.0.0
     */
    @Bean
    @Primary
    public ObjectMapper jacksonObjectMapper() {
        ObjectMapper globalObjectMapper = Jsons.getCopyMapper();
        if (this.jacksonProperties.getDefaultPropertyInclusion() != null) {
            globalObjectMapper.setSerializationInclusion(this.jacksonProperties.getDefaultPropertyInclusion());
        }
        // 添加 JDK8 的时间转换器
        globalObjectMapper.registerModule(new JavaTimeModule());
        globalObjectMapper.findAndRegisterModules();
        log.debug("初始化自定义 Jackson 配置 [{}]", globalObjectMapper);
        return globalObjectMapper;
    }

}

package dev.dong4j.zeka.starter.rest.autoconfigure.supportss;

import com.fasterxml.jackson.databind.ObjectMapper;

import org.jetbrains.annotations.NotNull;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.SmartInitializingSingleton;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingClass;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.http.client.ClientHttpRequestFactory;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.http.converter.HttpMessageConverter;
import org.springframework.http.converter.StringHttpMessageConverter;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.web.client.RestTemplate;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.TimeUnit;

import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocketFactory;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.exception.LowestException;
import dev.dong4j.zeka.kernel.common.ssl.DisableValidationTrustManager;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.util.Charsets;
import dev.dong4j.zeka.kernel.common.util.HttpsUtils;
import dev.dong4j.zeka.kernel.web.jackson.MappingApiJackson2HttpMessageConverter;
import dev.dong4j.zeka.starter.rest.autoconfigure.RestProperties;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * <p>Description: </p>
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dongshijie@gmail.com"
 * @date 2020.02.08 11:49
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration(after = JacksonConfiguration.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@EnableConfigurationProperties(RestProperties.class)
@ConditionalOnMissingClass("dev.dong4j.zeka.agent.adapter.config.AgentAdapterRestConfiguration")
public class RestTemplateAutoConfiguration implements ZekaAutoConfiguration {

    public RestTemplateAutoConfiguration() {
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 使用 okhttp, 忽略 https 证书
     * <p>
     * 注意：在Spring Boot 3.x中，OkHttp3ClientHttpRequestFactory已被删除
     * 我们使用自定义的OkHttpClientHttpRequestFactory来替代
     * 支持连接池配置
     *
     * @param restProperties rest properties
     * @return the client http request factory
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnClass(OkHttpClient.class)
    public ClientHttpRequestFactory clientHttpRequestFactory(@NotNull RestProperties restProperties) {
        // 获取支持SSL的OkHttpClient基础配置
        OkHttpClient baseClient = this.getUnsafeOkHttpClient();

        // 使用自定义的OkHttpClientHttpRequestFactory，支持连接池配置
        // 注意：这里我们需要将SSL配置传递给自定义工厂
        return new OkHttpClientHttpRequestFactory(
            // 传递SSL配置的OkHttpClient
            baseClient,
            restProperties.getConnectTimeout(),
            restProperties.getReadTimeout(),
            restProperties.getWriteTimeout(),
            restProperties.getConnectionPool().getMaxIdleConnections(),
            restProperties.getConnectionPool().getKeepAliveDuration(),
            TimeUnit.MINUTES
        );
    }

    /**
     * 创建并配置 RestTemplate 实例
     * <p> 该方法用于创建一个 RestTemplate 对象, 并使用提供的 ClientHttpRequestFactory 进行初始化, 同时添加自定义的消息转换器.</p>
     *
     * @param clientHttpRequestFactory 用于创建 HTTP 请求的工厂
     * @param objectMapper             用于序列化和反序列化 JSON 的对象映射器
     * @return 配置好的 RestTemplate 实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public RestTemplate restTemplate(ClientHttpRequestFactory clientHttpRequestFactory,
                                     @SuppressWarnings("SpringJavaInjectionPointsAutowiringInspection") ObjectMapper objectMapper) {
        RestTemplate restTemplate = new RestTemplate(clientHttpRequestFactory);
        this.converters(restTemplate, objectMapper);
        return restTemplate;
    }

    /**
     * Consumer rest template customizer
     *
     * @param listObjectProvider list object provider
     * @return the rest template customizer
     * @since 1.0.0
     */
    @Bean
    public RestTemplateCustomizer restConsumerRestTemplateCustomizer(
        ObjectProvider<List<ClientHttpRequestInterceptor>> listObjectProvider) {
        return restTemplate -> {
            Set<ClientHttpRequestInterceptor> set = new HashSet<>(restTemplate.getInterceptors());
            List<ClientHttpRequestInterceptor> clientHttpRequestInterceptors = listObjectProvider.getIfAvailable();
            if (clientHttpRequestInterceptors != null && !clientHttpRequestInterceptors.isEmpty()) {
                set.addAll(clientHttpRequestInterceptors);
            }
            // 自带排序
            restTemplate.setInterceptors(new ArrayList<>(set));
        };
    }

    /**
     * 在 bean 实例化后对 bean 进行处理, 遍历每个 RestTemplate, 将自定义拦截器添加到 RestTemplate.
     *
     * @param restConsumerRestTemplateCustomizer rest consumer rest template customizer
     * @param restTemplate                       rest template
     * @return the smart initializing singleton
     * @since 1.0.0
     */
    @Bean
    public SmartInitializingSingleton restTemplateSmartInitializingSingleton(RestTemplateCustomizer restConsumerRestTemplateCustomizer,
                                                                             RestTemplate restTemplate) {
        return () -> restConsumerRestTemplateCustomizer.customize(restTemplate);
    }

    /**
     * 添加消息转换器到 RestTemplate
     * <p> 该方法用于向 RestTemplate 添加自定义的消息转换器. 首先添加 UTF-8 编码的 StringHttpMessageConverter, 然后查找并移除已有的 MappingJackson2HttpMessageConverter,
     * 最后添加基于提供的 ObjectMapper 的 MappingApiJackson2HttpMessageConverter.</p>
     *
     * @param restTemplate 需要配置消息转换器的 RestTemplate 实例
     * @param objectMapper 用于序列化和反序列化 JSON 的对象映射器
     * @since 1.0.0
     */
    private void converters(@NotNull RestTemplate restTemplate, ObjectMapper objectMapper) {
        restTemplate.getMessageConverters().add(0, new StringHttpMessageConverter(Charsets.UTF_8));
        // 设置 json 转换器
        MappingApiJackson2HttpMessageConverter messageConverter = new MappingApiJackson2HttpMessageConverter(objectMapper);
        // 删除默认的 MappingJackson2HttpMessageConverter 转换器
        Iterator<HttpMessageConverter<?>> httpMessageConverterIterator = restTemplate.getMessageConverters().iterator();
        while (httpMessageConverterIterator.hasNext()) {
            if (httpMessageConverterIterator.next().getClass().isAssignableFrom(MappingJackson2HttpMessageConverter.class)) {
                httpMessageConverterIterator.remove();
                break;
            }
        }
        // 使用自定义 MappingJackson2HttpMessageConverter 转换器
        restTemplate.getMessageConverters().add(messageConverter);
    }


    /**
     * Gets unsafe ok http client *
     *
     * @return the unsafe ok http client
     * @since 1.0.0
     */
    @NotNull
    private OkHttpClient getUnsafeOkHttpClient() {

        try {
            SSLContext sslContext = HttpsUtils.getSslContext();
            SSLSocketFactory sslSocketFactory = sslContext.getSocketFactory();

            OkHttpClient.Builder builder = new OkHttpClient.Builder();
            builder.sslSocketFactory(sslSocketFactory, DisableValidationTrustManager.INSTANCE);
            builder.hostnameVerifier((hostname, session) -> true);
            return builder.build();
        } catch (Exception e) {
            throw new LowestException(e);
        }

    }
}

