package dev.dong4j.zeka.starter.mybatis.autoconfigure;

import org.springframework.boot.context.properties.ConfigurationProperties;

import dev.dong4j.zeka.kernel.autoconfigure.ZekaProperties;
import dev.dong4j.zeka.kernel.common.constant.ConfigKey;
import lombok.Getter;
import lombok.Setter;

/**
 * MyBatis 配置属性类
 * <p>
 * 该类用于定义 MyBatis 相关的配置属性，支持通过配置文件进行自定义配置。
 * 配置前缀为 "zeka-stack.mybatis"，包含以下主要配置项：
 * <p>
 * 1. SQL 日志配置：控制 SQL 语句的日志输出和格式化
 * 2. 性能监控配置：设置 SQL 执行时间阈值和输出长度限制
 * 3. 分页配置：设置默认的分页参数和单页限制
 * 4. 敏感数据配置：配置敏感字段加密的密钥
 * 5. 拦截器配置：控制各种 SQL 拦截器的开启状态
 * <p>
 * 所有配置项都有合理的默认值，可根据实际需求进行调整。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2025.06.29 16:49
 * @since 1.0.0
 */
@Getter
@Setter
@ConfigurationProperties(prefix = MybatisProperties.PREFIX)
public class MybatisProperties extends ZekaProperties {
    /** 组件配置前缀 */
    public static final String PREFIX = ConfigKey.PREFIX + "mybatis";

    /** sql 日志 */
    private boolean enableLog = false;
    /** 输出到日志的 sql 是否格式化 */
    private boolean sqlFormat = false;
    /** 超过 1000 毫秒的 sql 记录日志 */
    private Long performmaxTime = 1000L;
    /** 输出 sql 的最大长度 */
    private Integer maxLength = 1000;
    /** 附加SQL文件 */
    private boolean appendSqlFile = false;
    /** 分页默认起始页 */
    private Long page;
    /** 分页默认大小 */
    private Long limit;
    /** 单页限制 默认不限制 */
    private Long singlePageLimit = -1L;
    /** 敏感数据加密 AES_KEY */
    private String sensitiveKey = "rFsHHirtsGuST7HtBzebLge1uVYCg2ZS";
    /** sql 检查插件 */
    private boolean enableIllegalSqlInterceptor = Boolean.FALSE;
    /** SQL执行分析插件, 拦截一些整表操作 */
    private boolean enableSqlExplainInterceptor = Boolean.FALSE;

    /** 用于执行 JDBC 检查的实例 */
    private JdbcCheck jdbcCheck = new JdbcCheck();

    /**
     * JDBC 检查配置类
     * <p>
     * 用于控制是否启用 JDBC 相关的检查逻辑, 通过设置 enabled 属性来决定是否执行相关检查操作
     *
     * @author dong4j
     * @version 1.0.0
     * @email "mailto:dong4j@gmail.com"
     * @date 2025.12.14
     * @since 2.0.0
     */
    @Getter
    @Setter
    private static class JdbcCheck {
        /** 是否开启 */
        private boolean enabled = true;
    }
}

package dev.dong4j.zeka.starter.mybatis.autoconfigure;

import org.springframework.boot.context.properties.ConfigurationProperties;

import dev.dong4j.zeka.starter.mybatis.logger.ZekaP6spySlf4jLogger;
import lombok.Data;


/**
 * P6spy 配置属性类
 * <p>
 * 该类定义了 P6spy SQL 监控工具的默认配置属性，支持通过配置文件进行自定义。
 * 配置前缀为 "spring.datasource.p6spy"，主要配置项包括：
 * <p>
 * 1. 模块配置：定义要加载的 P6spy 模块列表
 * 2. 日志配置：设置日志消息格式和输出方式
 * 3. 驱动配置：指定要代理的数据库驱动
 * 4. 过滤配置：设置要排除的日志类别
 * 5. 慢查询配置：配置慢查询检测的时间阈值
 * 6. 格式配置：设置日期和时间戳的显示格式
 * <p>
 * 这些配置项都有合理的默认值，适用于大多数使用场景。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.12.15 10:03
 * @since 1.0.0
 */
@Data
@ConfigurationProperties(prefix = P6spyProperties.P6SPY_CONFIG_PREFIX)
public class P6spyProperties {

    /** P6SPY_CONFIG_PREFIX */
    public static final String P6SPY_CONFIG_PREFIX = "spring.datasource.p6spy";
    /** Enabled */
    private boolean enabled = false;
    /** Modulelist */
    private String modulelist = "com.baomidou.mybatisplus.extension.p6spy.MybatisPlusLogFactory,com.p6spy.engine.outage.P6OutageFactory";
    /**
     * Log message format
     *
     * @see ZekaP6spySlf4jLogger
     */
