/**
 * Knife4j自动配置类
 * <p>
 * 该类负责配置Knife4j相关的Bean和功能，提供API文档的增强功能。
 * 通过Spring Boot自动配置机制，在非生产环境下启用Knife4j功能。
 * <p>
 * 主要功能包括：
 * 1. 配置Knife4jOpenApiCustomizer自定义器
 * 2. 配置生产环境安全过滤器
 * 3. 提供Knife4j UI自动配置
 * 4. 支持OpenAPI文档的增强显示
 * <p>
 * 使用场景：
 * - API文档的自动生成和展示
 * - Swagger UI的增强功能
 * - OpenAPI规范的扩展支持
 * - 开发环境的API调试工具
 * <p>
 * 设计意图：
 * 通过自动配置简化Knife4j的集成，提供开箱即用的API文档功能，
 * 支持开发人员快速构建和调试API接口。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.05.08 16:14
 * @since 1.0.0
 */
@AutoConfiguration(before = com.github.xiaoymin.knife4j.spring.configuration.Knife4jAutoConfiguration.class)
@Profile(value = {App.ENV_NOT_PROD})
@ConditionalOnClass(value = {
    EnableKnife4j.class,
    Servlet.class,
    DispatcherServlet.class,
})
@ConditionalOnEnabled(value = OpenAPIProperties.PREFIX)
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
@EnableConfigurationProperties(value = {Knife4jProperties.class, com.github.xiaoymin.knife4j.spring.configuration.Knife4jProperties.class})
@Slf4j
public class Knife4jAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 构造Knife4j自动配置对象
     * <p>
     * 初始化Knife4j自动配置，记录启动日志。
     *
     * @since 1.0.0
     */
    public Knife4jAutoConfiguration() {
        log.info("启动自动配置: [{}]", this.getClass());
    }

    /**
     * 创建Knife4j OpenAPI自定义器
     * <p>
     * 创建自定义的Knife4j OpenAPI自定义器，用于增强API文档的显示和功能。
     * 该自定义器支持标签排序、文档扩展等高级功能。
     *
     * @param properties    Knife4j配置属性
     * @param docProperties SpringDoc配置属性
     * @return Knife4jOpenApiCustomizer实例
     * @since 1.0.0
     */
    @Bean
    public Knife4jOpenApiCustomizer knife4jOpenApiCustomizer(com.github.xiaoymin.knife4j.spring.configuration.Knife4jProperties properties,
                                                             SpringDocConfigProperties docProperties) {
        log.debug("Register Knife4jOpenApiCustomizer");
        return new MyKnife4jOpenApiCustomizer(properties, docProperties);
    }

    /**
     * 创建生产环境安全过滤器
     * <p>
     * 创建生产环境安全过滤器，用于在生产环境中保护API文档的访问。
     * 只有在非本地启动且为生产环境时才启用安全过滤。
     *
     * @return JakartaProductionSecurityFilter实例
     * @since 1.0.0
     */
    @Bean
    public JakartaProductionSecurityFilter productionSecurityFilter() {
        return new JakartaProductionSecurityFilter(!ConfigKit.isLocalLaunch() && ConfigKit.isProd());
    }

    /**
     * Knife4j UI自动配置类
     * <p>
     * 该类负责配置Knife4j UI相关的功能，仅在存在doc.html资源时启用。
     * 提供Swagger REST Bootstrap类型的库支持。
     *
     * @author dong4j
     * @version 1.0.0
     * @email "mailto:dong4j@gmail.com"
     * @date 2020.05.08 16:52
     * @since 1.0.0
     */
    @AutoConfiguration
    @ConditionalOnResource(resources = "classpath:META-INF/resources/doc.html")
    static class Knife4jUiAutoConfiguration implements ZekaAutoConfiguration {

        /**
         * 获取库类型
         * <p>
         * 返回Swagger REST Bootstrap库类型，用于标识当前使用的API文档库。
         *
         * @return SWAGGER_REST_BOOTSTRAP库类型
         * @since 1.0.0
         */
        @Override
        public LibraryEnum getLibraryType() {
            return LibraryEnum.SWAGGER_REST_BOOTSTRAP;
        }
    }

}

package dev.dong4j.zeka.starter.rest.autoconfigure;

import org.hibernate.validator.HibernateValidator;
import org.hibernate.validator.messageinterpolation.ParameterMessageInterpolator;
import org.jetbrains.annotations.NotNull;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;
import org.springframework.context.annotation.Profile;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.constant.App;
import dev.dong4j.zeka.kernel.common.enums.LibraryEnum;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.starter.rest.autoconfigure.reactive.WebFluxAutoConfiguration;
import dev.dong4j.zeka.starter.rest.autoconfigure.servlet.ServletAutoConfiguration;
import dev.dong4j.zeka.starter.rest.runner.OpenBrowserRunner;
import dev.dong4j.zeka.starter.rest.spi.RestLauncherInitiation;
import dev.dong4j.zeka.starter.rest.support.ZekaRestComponent;
import jakarta.validation.Validation;
import jakarta.validation.Validator;
import jakarta.validation.ValidatorFactory;
import lombok.extern.slf4j.Slf4j;

/**
 * REST 模块自动配置类
 * <p>
 * 该类作为 REST 模块的主要自动配置类，负责初始化和配置
 * 所有 REST 相关的核心组件和功能。
 * <p>
 * 主要功能：
 * 1. 注册 REST 模块组件标识
 * 2. 配置参数验证器（生产环境下开启快速失败模式）
 * 3. 初始化浏览器自动打开功能
 * 4. 与 Servlet 和 WebFlux 模块进行集成
 * <p>
 * 触发条件：
 * - 配置属性 zeka-stack.rest.enabled=true
 * - 应用为 Web 应用（Servlet 或 Reactive）
 * - 类路径中存在 RestLauncherInitiation 类
 * <p>
 * 加载顺序：
 * 在 ServletAutoConfiguration 和 WebFluxAutoConfiguration 之后加载，
 * 确保 Web 相关的配置已经完成。
 * <p>
 * 环境适配：
 * 自动适配不同的 Web 技术栈（Servlet 或 Reactive），
 * 提供统一的 REST API 开发体验。
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2025.06.29 10:44
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration(after = {
    ServletAutoConfiguration.class,
    WebFluxAutoConfiguration.class
})
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.ANY)
@EnableConfigurationProperties(RestProperties.class)
@ConditionalOnClass(RestLauncherInitiation.class)
public class RestAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 获取当前模块的库类型标识
     * <p>
     * 返回 REST 模块的类型标识，用于模块分类和管理。
     * 该标识由框架用于区分不同类型的组件和功能模块。
     * <p>
     * 作用：
     * - 模块分类和标识
     * - 依赖关系管理
     * - 组件扫描和加载
     * - 日志和监控信息分类
     *
     * @return REST 模块的库类型枚举值
     * @since 1.0.0
     */
    @Override
    public LibraryEnum getLibraryType() {
        return LibraryEnum.REST;
    }

    /**
     * 定义 REST 模块组件标识 Bean
     * <p>
     * 该方法创建并注册 REST 模块的组件标识 Bean，
     * 用于标识模块已经被正确加载和配置。
     * <p>
     * Bean 特性：
     * - 使用 @Primary 注解设为主要 Bean
     * - Bean 名称由 App.Components.REST_SPRING_BOOT 常量定义
     * - 在整个应用中保持唯一性
     * <p>
     * 作用：
     * - 模块状态监控和管理
     * - 其他模块的依赖检查
     * - 系统诊断和健康检查
     *
     * @return REST 模块组件标识实例
     * @since 1.0.0
     */
    @Primary
    @Bean(App.Components.REST_SPRING_BOOT)
    public ZekaRestComponent restComponent() {
        return new ZekaRestComponent();
    }

    /**
     * 配置参数验证器（生产环境下开启快速失败模式）
     * <p>
     * 在生产环境下，为了提高验证效率，将参数验证模式设置为快速失败。
     * 即遇到第一个验证错误时立即返回，而不是验证完所有参数后再返回所有错误。
     * <p>
     * 配置特点：
     * - 仅在生产环境（prod profile）下生效
     * - 使用 Hibernate Validator 作为验证提供者
     * - 开启快速失败模式（failFast=true）
     * - 使用参数消息插值器替代默认的 EL 表达式
     * <p>
     * 性能优势：
     * - 减少验证耗时，提高响应速度
     * - 降低 CPU 和内存开销
     * - 提高系统并发处理能力
     *
     * @return 配置为快速失败模式的验证器实例
     * @since 1.0.0
     */
    @Bean
    @Profile(value = {App.ENV_PROD})
    public Validator validator() {
        log.info("参数验证开启快速失败模式");
        try (ValidatorFactory validatorFactory = Validation.byProvider(HibernateValidator.class)
            .configure()
            // 快速失败模式：遇到第一个验证错误时立即返回
            .failFast(true)
            // 代替默认的 EL 表达式，提高性能和安全性
            .messageInterpolator(new ParameterMessageInterpolator())
            .buildValidatorFactory()) {
            return validatorFactory.getValidator();
        }
    }

    /**
     * 创建浏览器自动打开运行器
     * <p>
     * 该 Bean 用于在应用启动完成后自动打开浏览器访问应用首页。
     * 主要用于开发环境下提高开发者的体验。
     * <p>
     * 创建条件：
     * - 使用 @ConditionalOnMissingBean 确保只创建一个实例
     * - 允许用户自定义实现覆盖默认行为
     * <p>
     * 配置源：
     * 从 RestProperties 中获取 enableBrowser 配置，
     * 决定是否在应用启动后自动打开浏览器。
     * <p>
     * 功能特点：
     * - 仅在本地开发环境下生效
     * - 支持多平台（Windows、macOS、Linux）
     * - 延迟打开，确保服务完全就绪
     *
     * @param restProperties REST 模块的配置属性，不能为 null
     * @return 浏览器自动打开运行器实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public OpenBrowserRunner openBrowserRunner(@NotNull RestProperties restProperties) {
        return new OpenBrowserRunner(restProperties.isEnableBrowser());
    }
}

package dev.dong4j.zeka.starter.rest.autoconfigure.reactive;

import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.boot.web.reactive.context.ReactiveWebApplicationContext;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.reactive.config.WebFluxConfigurer;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.starter.rest.autoconfigure.RestProperties;
import dev.dong4j.zeka.starter.rest.handler.ZekaWebfluxExceptionErrorAttributes;
import jakarta.annotation.Resource;
import lombok.extern.slf4j.Slf4j;

/**
 * WebFlux 反应式 Web 自动配置类
 * <p>
 * 该自动配置类专门为基于 Spring WebFlux 的反应式 Web 应用提供配置支持。
 * 它负责初始化和配置 WebFlux 环境下所需的各种组件，包括路由配置、
 * 异常处理、请求处理等核心功能。
 * <p>
 * 主要功能：
 * 1. WebFlux 基础配置：为反应式 Web 应用提供基础的配置支持
 * 2. 异常处理集成：集成框架的自定义异常处理组件
 * 3. 环境检测：自动检测并适配 WebFlux 环境
 * 4. 配置管理：集成框架的配置属性管理
 * 5. 组件注册：为后续的组件注册提供基础支持
 * <p>
 * 条件化加载：
 * 1. @ConditionalOnWebApplication(REACTIVE)：仅在反应式 Web 环境下生效
 * 2. @ConditionalOnClass：检测 WebFlux 相关类的存在
 * 3. @ConditionalOnEnabled：支持通过配置文件开关功能
 * <p>
 * 配置依赖：
 * - WebFluxConfigurer：Spring WebFlux 配置接口
 * - ZekaWebfluxExceptionErrorAttributes：框架自定义的异常属性处理器
 * - ReactiveWebApplicationContext：反应式 Web 应用上下文
 * <p>
 * 设计特点：
 * - 实现 ZekaAutoConfiguration 接口，遵循框架规范
 * - 支持条件化加载，只在适当的环境下生效
 * - 集成框架的配置管理机制
 * - 提供明确的日志输出，便于问题排查
 * <p>
 * 使用场景：
 * - Spring Boot + WebFlux 反应式 Web 应用
 * - 微服务网关应用
 * - 高并发的 REST API 服务
 * - 流式数据处理应用
 * <p>
 * 注意事项：
 * - 该配置类与 Servlet 环境下的配置类互斥
 * - 需要确保项目中包含 WebFlux 相关依赖
 * - 建议与框架其他反应式组件配合使用
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2020.01.27 14:47
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@RestController
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.REACTIVE)
@ConditionalOnClass(value = {WebFluxConfigurer.class, ZekaWebfluxExceptionErrorAttributes.class})
@ConditionalOnEnabled(value = RestProperties.PREFIX)
public class WebFluxAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 构造函数，初始化 WebFlux 自动配置
     *
     * 在配置类实例化时被调用，用于记录配置的加载信息。
     * 这有助于在应用启动时跟踪哪些自动配置被激活，
     * 便于问题排查和系统监控。
     */

    /** 反应式 Web 应用上下文，用于访问 WebFlux 环境下的 Spring 容器和组件 */
    @Resource
    private ReactiveWebApplicationContext applicationContext;

}

