/**
 * WebFlux 全局异常处理自动配置类
 * <p>
 * 该配置类专门为 WebFlux 反应式环境提供全局异常处理能力。它负责注册和配置
 * 自定义的异常处理器，替代 Spring Boot 默认的异常处理机制，为 WebFlux 应用
 * 提供更加一致和专业的错误响应处理。
 * <p>
 * 主要功能：
 * 1. 注册自定义的 JsonErrorWebExceptionHandler，替代默认异常处理器
 * 2. 配置 ZekaWebfluxExceptionErrorAttributes，提供自定义的错误属性提取
 * 3. 集成 WebFlux 的编解码器配置，支持多种数据格式
 * 4. 配置视图解析器，支持多种视图模板技术
 * 5. 根据环境自动调整异常信息的详细程度
 * <p>
 * 配置组件：
 * - {@link JsonErrorWebExceptionHandler}：自定义的 JSON 格式异常处理器
 * - {@link ZekaWebfluxExceptionErrorAttributes}：自定义的错误属性提取器
 * - {@link ServerCodecConfigurer}：服务器编解码器配置
 * <p>
 * 条件化加载：
 * 1. @ConditionalOnWebApplication(REACTIVE)：仅在反应式 Web 环境下生效
 * 2. @ConditionalOnClass：检测 WebFlux 相关类的存在
 * 3. @ConditionalOnEnabled：支持通过配置文件开关功能
 * 4. @ConditionalOnMissingBean：避免与用户自定义的 Bean 冲突
 * <p>
 * 加载顺序：
 * 通过 @AutoConfiguration(before = WebFluxAutoConfiguration.class) 确保
 * 在 Spring Boot 的 WebFlux 自动配置之前加载，保证配置的优先级。
 * <p>
 * 异常处理优先级：
 * 通过 @Order(-2) 设置高优先级，确保自定义的异常处理器
 * 能够拦截所有未处理的异常。
 * <p>
 * 环境适配：
 * - 开发环境：提供详细的异常信息，包括堆栈跟踪
 * - 生产环境：只提供必要的错误信息，保护系统安全
 * <p>
 * 配置属性：
 * - ServerProperties：服务器配置，包括错误页面路径等
 * - WebProperties：静态资源配置，用于错误页面等
 * <p>
 * 设计特点：
 * - 可覆盖性：允许用户通过自定义 Bean 覆盖默认配置
 * - 模块化：各个组件独立配置，便于维护和扩展
 * - 集成性：与 Spring Boot 和 WebFlux 的现有配置紧密集成
 * - 灵活性：支持条件化加载和配置覆盖
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2019.11.20 10:24
 * @since 1.0.0
 */
@Slf4j
@ConditionalOnClass(value = {WebFluxConfigurer.class, ZekaWebfluxExceptionErrorAttributes.class})
@AutoConfiguration(before = WebFluxAutoConfiguration.class)
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.REACTIVE)
@EnableConfigurationProperties(value = {ServerProperties.class, WebProperties.class})
public class WebfluxGlobalExceptionAutoConfiguration implements ZekaAutoConfiguration {
    /** 服务器配置属性，包含错误处理、端口等配置信息 */
    private final ServerProperties serverProperties;
    /** Spring 应用上下文，用于访问其他 Bean 和组件 */
    private final ApplicationContext applicationContext;
    /** Web 资源配置属性，包含静态资源路径等配置 */
    private final WebProperties resourceProperties;
    /** 视图解析器列表，用于处理错误页面的渲染 */
    private final List<ViewResolver> viewResolvers;
    /** 服务器编解码器配置，用于处理 HTTP 请求和响应的编解码 */
    private final ServerCodecConfigurer serverCodecConfigurer;

    /**
     * 构造函数，初始化 WebFlux 全局异常处理自动配置
     * <p>
     * 该构造函数负责初始化全局异常处理所需的所有组件和配置。
     * 它会收集和设置各种依赖组件，为后续的 Bean 注册做准备。
     * <p>
     * 初始化包括：
     * 1. 服务器基础配置信息
     * 2. Web 资源和静态文件配置
     * 3. 视图解析器集合，支持多种模板技术
     * 4. 编解码器配置，处理请求和响应的数据转换
     * 5. Spring 应用上下文引用
     *
     * @param serverProperties      服务器配置属性，包含端口、错误处理等配置
     * @param resourceProperties    Web 资源配置属性，包含静态资源路径等
     * @param viewResolversProvider 视图解析器提供者，自动收集所有注册的视图解析器
     * @param serverCodecConfigurer 服务器编解码器配置，用于 HTTP 消息的序列化
     * @param applicationContext    Spring 应用上下文，用于访问其他 Bean
     * @since 1.0.0
     */
    public WebfluxGlobalExceptionAutoConfiguration(ServerProperties serverProperties,
                                                   WebProperties resourceProperties,
                                                   @NotNull ObjectProvider<ViewResolver> viewResolversProvider,
                                                   ServerCodecConfigurer serverCodecConfigurer,
                                                   ApplicationContext applicationContext) {
        log.info("启动自动配置: [{}]", this.getClass());

        this.serverProperties = serverProperties;
        this.applicationContext = applicationContext;
        this.resourceProperties = resourceProperties;
        this.viewResolvers = viewResolversProvider.orderedStream().collect(Collectors.toList());
        this.serverCodecConfigurer = serverCodecConfigurer;
    }

    /**
     * 注册默认的服务器编解码器配置
     * <p>
     * 该方法会在系统中没有其他 ServerCodecConfigurer Bean 时提供一个默认实现。
     * 编解码器配置用于处理 WebFlux 中 HTTP 请求和响应的数据转换，
     * 支持 JSON、XML、表单数据等多种数据格式。
     * <p>
     * 功能特点：
     * - 支持多种数据格式的编解码
     * - 与 WebFlux 的响应式流处理机制集成
     * - 可以被用户自定义的配置覆盖
     *
     * @return 默认的服务器编解码器配置实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public ServerCodecConfigurer serverCodecConfigurer() {
        return new DefaultServerCodecConfigurer();
    }

    /**
     * 注册自定义的全局异常处理器
     * <p>
     * 该方法创建并配置了自定义的 JsonErrorWebExceptionHandler，用于替代
     * Spring Boot 默认的 DefaultErrorWebExceptionHandler。这个自定义处理器
     * 会将所有异常转换为统一的 JSON 格式响师。
     * <p>
     * 配置包括：
     * 1. 错误属性提取器：用于从异常中提取信息
     * 2. 资源配置：用于错误页面等静态资源的处理
     * 3. 服务器错误配置：包括错误页面路径等
     * 4. 应用上下文：用于访问其他 Spring Bean
     * 5. 视图解析器：用于处理模板渲染
     * 6. 消息编解码器：用于 HTTP 消息的序列化和反序列化
     * <p>
     * 优先级设置：
     * 通过 @Order(-2) 设置高优先级，确保在所有其他异常处理器
     * 之前被调用，实现真正的全局异常拦截。
     *
     * @param errorAttributes 错误属性提取器，由 Spring 自动注入
     * @return 配置完成的自定义异常处理器
     * @since 1.0.0
     */
    @Bean
    @Order(-2)
    public ErrorWebExceptionHandler errorWebExceptionHandler(ErrorAttributes errorAttributes) {
        log.info("初始化自定义全局异常处理器: {}", JsonErrorWebExceptionHandler.class);
        JsonErrorWebExceptionHandler exceptionHandler = new JsonErrorWebExceptionHandler(errorAttributes,
                                                                                         this.resourceProperties.getResources(),
                                                                                         this.serverProperties.getError(),
                                                                                         this.applicationContext);
        exceptionHandler.setViewResolvers(this.viewResolvers);
        exceptionHandler.setMessageWriters(this.serverCodecConfigurer.getWriters());
        exceptionHandler.setMessageReaders(this.serverCodecConfigurer.getReaders());
        return exceptionHandler;
    }

    /**
     * 注册自定义的错误属性提取器
     * <p>
     * 该方法创建了自定义的 ZekaWebfluxExceptionErrorAttributes，替代 Spring Boot
     * 默认的 DefaultErrorAttributes。这个自定义实现会根据环境配置提供
     * 不同级别的错误信息。
     * <p>
     * 环境适配特性：
     * - 开发环境 (!ConfigKit.isProd())：
     * * 包含详细的异常信息，如堆栈跟踪
     * * 包含请求参数和请求头信息
     * * 方便开发人员进行问题排查
     * <p>
     * - 生产环境 (ConfigKit.isProd())：
     * * 只返回基本的错误信息
     * * 保护系统内部信息安全
     * * 避免泄露敏感的技术细节
     * <p>
     * 条件化注册：
     * 只有在当前上下文中没有其他 ErrorAttributes 类型的 Bean 时
     * 才会注册该实例，保证用户可以通过自定义 Bean 覆盖默认行为。
     *
     * @return 按环境配置的错误属性提取器实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(value = ErrorAttributes.class, search = SearchStrategy.CURRENT)
    public DefaultErrorAttributes errorAttributes() {
        return new ZekaWebfluxExceptionErrorAttributes(!ConfigKit.isProd());
    }

}

package dev.dong4j.zeka.starter.rest.autoconfigure.servlet;

import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;
import org.springframework.boot.autoconfigure.web.ServerProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.web.method.support.HandlerMethodReturnValueHandler;
import org.springframework.web.servlet.DispatcherServlet;
import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerAdapter;
import org.springframework.web.servlet.mvc.method.annotation.RequestResponseBodyMethodProcessor;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import dev.dong4j.zeka.kernel.autoconfigure.condition.ConditionalOnEnabled;
import dev.dong4j.zeka.kernel.common.start.ZekaAutoConfiguration;
import dev.dong4j.zeka.kernel.common.util.CollectionUtils;
import dev.dong4j.zeka.starter.rest.autoconfigure.RestProperties;
import dev.dong4j.zeka.starter.rest.autoconfigure.supportss.XssProperties;
import dev.dong4j.zeka.starter.rest.handler.CustomizeReturnValueHandler;
import dev.dong4j.zeka.starter.rest.handler.ZekaServletExceptionErrorAttributes;
import dev.dong4j.zeka.starter.rest.interceptor.AuthenticationInterceptor;
import dev.dong4j.zeka.starter.rest.interceptor.CurrentUserInterceptor;
import dev.dong4j.zeka.starter.rest.interceptor.TraceInterceptor;
import dev.dong4j.zeka.starter.rest.support.CurrentUserArgumentResolver;
import dev.dong4j.zeka.starter.rest.support.CurrentUserService;
import jakarta.servlet.Servlet;
import lombok.extern.slf4j.Slf4j;

/**
 * Servlet Web 环境 REST 自动配置类
 * <p>
 * 该自动配置类专门为基于 Servlet 的传统 Web 应用提供 REST 相关的自动配置支持。
 * 它负责注册和配置 Servlet 环境下所需的各种组件，包括拦截器、参数解析器、
 * 返回值处理器等核心组件。
 * <p>
 * 主要功能：
 * 1. 用户信息处理：注册当前用户参数解析器和相关服务
 * 2. 请求拦截：配置用户认证、链路追踪等拦截器
 * 3. 返回值处理：自定义返回值处理器，实现统一响应格式
 * 4. 错误处理：集成自定义的异常属性处理器
 * 5. XSS 防护：集成 XSS 攻击防护机制
 * <p>
 * 注册的核心组件：
 * - {@link CurrentUserArgumentResolver}：当前用户参数解析器
 * - {@link CurrentUserService}：当前用户信息服务
 * - {@link CurrentUserInterceptor}：当前用户拦截器
 * - {@link AuthenticationInterceptor}：Token 认证拦截器
 * - {@link TraceInterceptor}：链路追踪拦截器
 * - {@link CustomizeReturnValueHandler}：自定义返回值处理器
 * <p>
 * 条件化加载：
 * 1. @ConditionalOnWebApplication(SERVLET)：仅在 Servlet Web 环境下生效
 * 2. @ConditionalOnClass：检测 Servlet 和 Spring MVC 相关类的存在
 * 3. @ConditionalOnEnabled：支持通过配置文件开关功能
 * 4. @ConditionalOnMissingBean：避免与用户自定义 Bean 冲突
 * <p>
 * 内部配置类：
 * 包含一个内部的 ConsumerMethodReturnValueHandlerAutoConfiguration 配置类，
 * 用于处理返回值处理器的优先级问题。
 * <p>
 * 设计特点：
 * - 模块化设计：各个功能组件独立注册，便于维护和扩展
 * - 条件化配置：支持用户自定义覆盖默认行为
 * - 优先级处理：通过内部配置类解决组件加载顺序问题
 * - 集成性：与 Spring Boot 和 Spring MVC 的现有配置紧密集成
 * <p>
 * 使用场景：
 * - 传统的 Spring Boot Web 应用
 * - REST API 服务
 * - 微服务中的业务服务
 * - 需要用户认证和权限控制的 Web 应用
 * <p>
 * 注意事项：
 * - 该配置类与 WebFlux 环境下的配置类互斥
 * - 部分组件依赖特定的三方库，如 JWT 处理等
 * - 建议与框架其他 Web 相关组件配合使用
 *
 * @author dong4j
 * @version 1.0.0
 * @email "mailto:dong4j@gmail.com"
 * @date 2019.11.21 21:41
 * @since 1.0.0
 */
@Slf4j
@AutoConfiguration
@EnableConfigurationProperties(value = {ServerProperties.class, XssProperties.class})
@ConditionalOnClass(value = {Servlet.class, DispatcherServlet.class, ZekaServletExceptionErrorAttributes.class})
@ConditionalOnEnabled(value = RestProperties.PREFIX)
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
public class ServletAutoConfiguration implements ZekaAutoConfiguration {

    /**
     * 注册当前用户参数解析器
     * <p>
     * 该方法注册了一个用于解析 @CurrentUser 注解参数的解析器。
     * 它能够自动从 HTTP 请求中提取用户信息，并将其注入到
     * Controller 方法的参数中，简化用户信息的获取逻辑。
     * <p>
     * 功能特点：
     * - 支持从 JWT Token 中自动解析用户信息
     * - 支持从 HTTP 请求头中获取用户标识
     * - 提供默认的异常处理机制
     *
     * @return 当前用户参数解析器实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public CurrentUserArgumentResolver currentUserArgumentResolver() {
        return new CurrentUserArgumentResolver();
    }

    /**
     * 注册当前用户信息服务
     * <p>
     * 该方法注册了一个默认的当前用户信息服务实现。这个服务提供了
     * 从 HTTP 请求中提取用户信息的标准方法，包括 JWT Token 解析、
     * 请求头处理等功能。
     * <p>
     * 默认实现特点：
     * - 使用接口的默认方法实现
     * - 支持基于 JWT 的用户认证
     * - 提供扩展点供用户自定义实现
     * - 与框架的认证机制集成
     *
     * @return 当前用户信息服务的默认实现
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public CurrentUserService currentUserService() {
        return new CurrentUserService() {
        };
    }

    /**
     * 注册当前用户拦截器
     * <p>
     * 该方法注册了一个用于处理当前用户信息的拦截器。该拦截器会
     * 在请求处理过程中自动解析和设置当前用户信息，为后续的
     * Controller 方法提供用户上下文。
     * <p>
     * 功能说明：
     * - 在请求进入 Controller 之前解析用户信息
     * - 为后续的参数解析器提供用户上下文
     * - 支持用户信息的缓存和传递
     * - 与 Spring Security 等安全框架集成
     *
     * @param currentUserService 当前用户信息服务，用于解析用户信息
     * @return 当前用户拦截器实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public CurrentUserInterceptor currentUserInterceptor(CurrentUserService currentUserService) {
        return new CurrentUserInterceptor(currentUserService);
    }

    /**
     * 注册认证拦截器
     * <p>
     * 该方法注册了一个用于处理 API 认证的拦截器。该拦截器基于
     *
     * @param currentUserService 当前用户信息服务，用于验证和解析用户信息
     * @return 认证拦截器实例
     * @TokenRequired 注解进行工作，只有标记了该注解的 API 才会进行
     *     Token 认证检查。
     *     <p>
     *     认证特点：
     *     - 基于注解的认证机制，精确控制到方法级别
     *     - 支持 JWT Token 的验证和解析
     *     - 提供明确的错误信息和异常处理
     *     - 不影响 API 文档的可读性
     *     <p>
     *     优势：
     *     - 相比于在 Controller 方法中直接注入 CurrentUser
     *     - 避免在 Swagger 等 API 文档中显示不必要的参数
     *     - 提供更加灵活和精准的认证控制
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean
    public AuthenticationInterceptor authenticationInterceptor(CurrentUserService currentUserService) {
        return new AuthenticationInterceptor(currentUserService);
    }

    /**
     * 注册链路追踪拦截器
     * <p>
     * 该方法注册了一个用于生成和管理链路追踪 ID 的拦截器。
     * 默认情况下使用 UUID 作为 traceId，如果项目中集成了 Tracer
     * 组件（如 Zipkin、Jaeger等），则会被替换为更专业的实现。
     * <p>
     * 功能说明：
     * - 为每个 HTTP 请求生成唯一的链路追踪 ID
     * - 在请求处理过程中保持 traceId 的传递
     * - 支持与分布式追踪系统集成
     * - 在请求结束后自动清理上下文
     * <p>
     * 使用场景：
     * - 分布式系统中的请求链路追踪
     * - 问题排查和日志关联
     * - 性能监控和分析
     * - 业务流程的全链路跟踪
     *
     * @return 链路追踪拦截器实例
     * @since 1.0.0
     */
    @Bean
    @ConditionalOnMissingBean(TraceInterceptor.class)
    public TraceInterceptor restTraceInterceptor() {
        return new TraceInterceptor();
    }


    /**
     * 返回值处理器自动配置类
     * <p>
     * 该内部静态配置类专门用于解决 Spring MVC 中返回值处理器的优先级问题。
     * 由于在 {@link ServletWebAutoConfiguration} 中配置的 {@link HandlerMethodReturnValueHandler}
     * 优先级最低，因此需要通过这种方式来修改和优化处理器的执行顺序。
     * <p>
     * 问题背景：
     * Spring MVC 的返回值处理器是按照注册顺序执行的，而自动配置的
     * 处理器通常最后注册，导致自定义的处理逻辑无法生效。
     * <p>
     * 解决方案：
     * 1. 获取已注册的所有返回值处理器
     * 2. 找到 RequestResponseBodyMethodProcessor 实例
     * 3. 用自定义的 CustomizeReturnValueHandler 装饰器替换它
     * 4. 重新设置处理器列表，确保自定义逻辑生效
     * <p>
     * 数据流转：
     * 原始请求 → RequestMappingHandlerAdapter → CustomizeReturnValueHandler → 统一响师格式
     * <p>
     * 设计特点：
     * - 使用静态内部类，避免不必要的实例引用
     * - 实现 ZekaAutoConfiguration 接口，支持初始化后处理
     * - 条件化加载，只在需要时才激活
     * - 装饰器模式，保留原有功能并增强特性
     *
     * @author dong4j
     * @version 1.0.0
     * @email "mailto:dong4j@gmail.com"
     * @date 2020.12.07 14:40
     * @since 1.0.0
     */
    @Slf4j
    @AutoConfiguration
    @ConditionalOnBean(RequestMappingHandlerAdapter.class)
    @ConditionalOnEnabled(value = RestProperties.PREFIX)
    static class ConsumerMethodReturnValueHandlerAutoConfiguration implements ZekaAutoConfiguration {
        /** Spring MVC 请求映射处理器适配器，用于管理和配置返回值处理器 */
        private final RequestMappingHandlerAdapter adapter;

        /**
         * 构造函数，初始化返回值处理器自动配置
         * <p>
         * 该构造函数使用 ObjectProvider 来延迟获取 RequestMappingHandlerAdapter，
         * 这样可以确保在 Spring 容器完全初始化后再进行处理器的修改。
         *
         * @param adapter RequestMappingHandlerAdapter 提供者，用于延迟获取适配器实例
         */
        ConsumerMethodReturnValueHandlerAutoConfiguration(ObjectProvider<RequestMappingHandlerAdapter> adapter) {
            log.info("启动自动配置: [{}]", this.getClass());
            if (adapter.getIfAvailable() != null) {
                this.adapter = adapter.getIfAvailable();
            } else {
                this.adapter = null;
            }
        }

        /**
         * 在属性设置完成后执行的初始化方法
         * <p>
         * 该方法会在 Spring 容器初始化完成后被自动调用，用于修改
         * RequestMappingHandlerAdapter 中的返回值处理器列表。
         * <p>
         * 执行流程：
         * 1. 检查 RequestMappingHandlerAdapter 是否可用
         * 2. 获取已注册的所有返回值处理器
         * 3. 创建新的处理器列表副本
         * 4. 对处理器列表进行装饰和优化
         * 5. 重新设置优化后的处理器列表
         *
         * @since 1.0.0
         */
        @Override
        public void afterPropertiesSet() {
            if (this.adapter != null) {
                List<HandlerMethodReturnValueHandler> returnValueHandlers = this.adapter.getReturnValueHandlers();
                List<HandlerMethodReturnValueHandler> handlers = Collections.emptyList();
                if (CollectionUtils.isNotEmpty(returnValueHandlers)) {
                    handlers = new ArrayList<>(returnValueHandlers);
                }
                this.decorateHandlers(handlers);
                this.adapter.setReturnValueHandlers(handlers);
            }
        }

        /**
         * 装饰和优化返回值处理器列表
         * <p>
         * 该方法会遍历所有的返回值处理器，找到 RequestResponseBodyMethodProcessor
         * 实例并用自定义的 CustomizeReturnValueHandler 装饰器替换它。
         * <p>
         * 替换策略：
         * 1. 遍历所有已注册的返回值处理器
         * 2. 检查是否为 RequestResponseBodyMethodProcessor 类型
         * 3. 如果是，则创建 CustomizeReturnValueHandler 装饰器
         * 4. 在原位置替换成装饰器实例
         * 5. 一旦找到并替换完成，就退出循环
         * <p>
         * 这种设计保证了：
         * - 保持原有处理器的所有功能
         * - 在不影响性能的前提下增加自定义逻辑
         * - 保持与 Spring MVC 框架的兼容性
         *
         * @param handlers 需要装饰的返回值处理器列表
         * @since 1.0.0
         */
        private void decorateHandlers(List<HandlerMethodReturnValueHandler> handlers) {
            for (HandlerMethodReturnValueHandler handler : handlers) {
                if (handler instanceof RequestResponseBodyMethodProcessor) {
                    CustomizeReturnValueHandler decorator = new CustomizeReturnValueHandler(
                        (RequestResponseBodyMethodProcessor) handler);
                    int index = handlers.indexOf(handler);
                    handlers.set(index, decorator);
                    break;
                }
            }
        }
    }
}

